-- >>> 0001_foundation.sql
-- =============================================================================
-- MessMate BD · 0001 · Foundation
-- Schemas, extensions, enums and small utility helpers used by every module.
--
-- Run the migrations in order (0001 → 0012) in the Supabase SQL editor, or paste
-- the bundled supabase/setup.sql once. 0013 (pg_cron) is run separately.
--
-- Conventions
--   * Every SECURITY DEFINER function pins `search_path = ''` and uses fully
--     qualified names, so it cannot be hijacked by objects in other schemas.
--   * RPCs raise short snake_case error keys (e.g. 'insufficient_balance');
--     the frontend maps them to Bangla / English messages.
--   * Money is numeric(12,2) in Taka. Dates use the Asia/Dhaka calendar.
-- =============================================================================

create schema if not exists private;
comment on schema private is 'MessMate internal helpers. Not exposed through the Data API.';
grant usage on schema private to anon, authenticated, service_role;

create extension if not exists pgcrypto with schema extensions;

-- -----------------------------------------------------------------------------
-- Enums
-- -----------------------------------------------------------------------------
create type public.platform_role     as enum ('user', 'landlord', 'service_provider', 'super_admin');
create type public.mess_role         as enum ('manager', 'member');
create type public.member_status     as enum ('pending', 'active', 'inactive', 'rejected', 'left');
create type public.occupation_type   as enum ('student', 'job_holder', 'business', 'other');
create type public.gender_type       as enum ('male', 'female', 'other');
create type public.room_type         as enum ('single', 'double', 'shared', 'seat');

create type public.meal_slot         as enum ('breakfast', 'lunch', 'dinner');
create type public.meal_rate_mode    as enum ('auto', 'fixed');
create type public.order_status      as enum ('ordered', 'cancelled');

create type public.ledger_type       as enum (
  'deposit',        -- money in (approved bKash/Nagad/Rocket/cash)
  'meal_charge',    -- meal cost (fixed price at order time, or meal-rate at month close)
  'meal_refund',    -- fixed-mode meal cancelled before cutoff
  'bill_share',     -- member share of a posted bill or shared expense
  'reimbursement',  -- member paid a mess expense from own pocket
  'adjustment',     -- manual correction by manager (signed)
  'refund_payout',  -- manager returned money to member (e.g. leaving the mess)
  'reversal'        -- exact negation of an earlier entry
);
create type public.payment_method    as enum ('bkash', 'nagad', 'rocket', 'cash', 'bank');
create type public.request_status    as enum ('pending', 'approved', 'rejected');
create type public.expense_category  as enum ('bazar', 'cooking_gas', 'utensils', 'cleaning', 'repair', 'other');
create type public.expense_payer     as enum ('mess_fund', 'member');
create type public.bill_type         as enum ('rent', 'electricity', 'gas', 'water', 'wifi', 'bua', 'service_charge', 'other');
create type public.split_mode        as enum ('equal', 'by_room', 'custom');
create type public.bill_status       as enum ('draft', 'posted', 'void');

create type public.listing_type      as enum ('seat', 'room', 'flat', 'sublet');
create type public.moderation_status as enum ('pending', 'approved', 'rejected', 'archived');
create type public.gender_pref       as enum ('male', 'female', 'any');
create type public.tenant_pref       as enum ('student', 'job_holder', 'any');
create type public.move_kind         as enum ('move_in', 'move_out');

create type public.complaint_category as enum ('bua', 'landlord', 'load_shedding', 'water', 'gas', 'wifi', 'noise', 'cleanliness', 'security', 'other');
create type public.complaint_status  as enum ('open', 'in_progress', 'resolved', 'closed');
create type public.priority_level    as enum ('low', 'normal', 'high', 'urgent');
create type public.chore_type        as enum ('bazar', 'cleaning', 'cooking_help', 'garbage', 'water_filter', 'other');
create type public.chore_status      as enum ('pending', 'done', 'skipped');
create type public.service_category  as enum ('bua_cook', 'tiffin', 'electrician', 'plumber', 'gas_cylinder', 'internet', 'laundry', 'tutor', 'moving_van', 'doctor', 'other');
create type public.market_category   as enum ('furniture', 'bed', 'fan', 'electronics', 'books', 'kitchen', 'clothing', 'other');
create type public.item_condition    as enum ('new', 'like_new', 'good', 'fair');
create type public.market_status     as enum ('available', 'reserved', 'sold', 'removed');
create type public.place_kind        as enum ('hospital', 'pharmacy', 'police', 'fire_service', 'ambulance', 'blood_bank', 'helpline', 'mental_health');
create type public.budget_entry_type as enum ('income', 'expense');
create type public.budget_category   as enum ('food', 'rent', 'transport', 'mobile_internet', 'education', 'health', 'family', 'shopping', 'entertainment', 'savings', 'salary', 'tuition_income', 'other');

create type public.mood_level        as enum ('great', 'good', 'okay', 'tired', 'sad', 'stressed');
create type public.care_alert_type   as enum ('sick', 'sos');
create type public.care_alert_status as enum ('active', 'acknowledged', 'resolved');
create type public.checkin_status    as enum ('pending', 'arrived', 'overdue', 'cancelled');
create type public.reminder_type     as enum ('medicine', 'water', 'sleep', 'call_home', 'rent', 'bill', 'custom');
create type public.loan_direction    as enum ('lent', 'borrowed');
create type public.loan_status       as enum ('open', 'settled');
create type public.event_type        as enum ('iftar', 'eid', 'puja', 'meetup', 'sports', 'study', 'other');
create type public.job_type          as enum ('tuition', 'part_time', 'freelance', 'internship');
create type public.job_status        as enum ('open', 'closed', 'removed');
create type public.cook_equipment    as enum ('rice_cooker', 'stove', 'kettle', 'no_cook');
create type public.feedback_type     as enum ('feedback', 'bug', 'contact', 'report');
create type public.feedback_status   as enum ('new', 'reviewing', 'resolved');

-- -----------------------------------------------------------------------------
-- Utility helpers
-- -----------------------------------------------------------------------------

-- Today's date on the Dhaka calendar (the server runs in UTC).
create or replace function private.dhaka_today()
returns date
language sql stable
set search_path = ''
as $$
  select (now() at time zone 'Asia/Dhaka')::date
$$;

-- First day of the month that contains p_date.
create or replace function private.month_start(p_date date)
returns date
language sql immutable
set search_path = ''
as $$
  select date_trunc('month', p_date::timestamp)::date
$$;

-- A Dhaka wall-clock date + time as an absolute timestamp.
create or replace function private.dhaka_ts(p_date date, p_time time)
returns timestamptz
language sql immutable
set search_path = ''
as $$
  select (p_date + p_time) at time zone 'Asia/Dhaka'
$$;

create or replace function private.try_uuid(p_text text)
returns uuid
language plpgsql immutable
set search_path = ''
as $$
begin
  return p_text::uuid;
exception when others then
  return null;
end;
$$;

-- True when the statement is not coming from an end user: SQL editor, pg_cron,
-- Supabase Auth internals. Requests through the Data API always run as
-- anon/authenticated via the `authenticator` login role.
create or replace function private.is_system_call()
returns boolean
language sql stable
set search_path = ''
as $$
  select auth.uid() is null
     and session_user::text <> 'authenticator'
     and coalesce(nullif(current_setting('role', true), ''), 'none') not in ('anon', 'authenticated', 'authenticator')
$$;

-- Transaction-local flag our own RPCs set before touching guarded columns.
-- End users cannot set it: the private schema is not exposed by the Data API.
create or replace function private.is_internal()
returns boolean
language sql stable
set search_path = ''
as $$
  select coalesce(current_setting('messmate.internal', true), '') = 'on'
$$;

create or replace function private.set_internal(p_on boolean)
returns void
language plpgsql volatile
set search_path = ''
as $$
begin
  perform set_config('messmate.internal', case when p_on then 'on' else 'off' end, true);
end;
$$;

-- Demo/data purge mode (used only by supabase/remove_demo.sql from the SQL editor).
create or replace function private.is_purge()
returns boolean
language sql stable
set search_path = ''
as $$
  select private.is_system_call() and coalesce(current_setting('messmate.purge', true), '') = 'on'
$$;

create or replace function private.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- 8-character invite code without look-alike characters (no 0/O, 1/I).
create or replace function private.new_invite_code()
returns text
language plpgsql volatile
set search_path = ''
as $$
declare
  v_alphabet constant text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_bytes bytea := extensions.gen_random_bytes(8);
  v_code text := '';
begin
  for i in 0..7 loop
    v_code := v_code || substr(v_alphabet, (get_byte(v_bytes, i) % 32) + 1, 1);
  end loop;
  return v_code;
end;
$$;

create or replace function private.taka(p_amount numeric)
returns text
language sql immutable
set search_path = ''
as $$
  select '৳' || trim(to_char(round(p_amount, 2), 'FM999999999990.00'))
$$;


-- >>> 0002_core.sql
-- =============================================================================
-- MessMate BD · 0002 · Core: areas, profiles, messes, membership, platform
-- Multi-tenant model: a mess is the tenant. A user has at most ONE open
-- membership (pending / active / inactive) at a time.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Dhaka areas (reference data is loaded in 0012)
-- -----------------------------------------------------------------------------
create table public.areas (
  id          smallint generated always as identity primary key,
  slug        text not null unique check (slug ~ '^[a-z0-9-]+$'),
  name_bn     text not null check (char_length(name_bn) between 2 and 60),
  name_en     text not null check (char_length(name_en) between 2 and 60),
  lat         numeric(9,6),
  lng         numeric(9,6),
  sort_order  smallint not null default 100
);

-- -----------------------------------------------------------------------------
-- Profiles (1:1 with auth.users)
-- -----------------------------------------------------------------------------
create table public.profiles (
  id                 uuid primary key references auth.users (id) on delete cascade,
  full_name          text not null default '' check (char_length(full_name) <= 80),
  email              text,
  phone              text check (phone ~ '^\+?[0-9]{10,14}$'),
  avatar_url         text check (char_length(avatar_url) <= 500),
  platform_role      public.platform_role not null default 'user',
  gender             public.gender_type,
  occupation         public.occupation_type,
  institution        text check (char_length(institution) <= 120),
  home_district      text check (char_length(home_district) <= 60),
  blood_group        text check (blood_group in ('A+', 'A-', 'B+', 'B-', 'AB+', 'AB-', 'O+', 'O-')),
  guardian_name      text check (char_length(guardian_name) <= 80),
  guardian_phone     text check (guardian_phone ~ '^\+?[0-9]{10,14}$'),
  bio                text check (char_length(bio) <= 300),
  preferred_locale   text not null default 'bn' check (preferred_locale in ('bn', 'en')),
  terms_accepted_at  timestamptz,
  terms_version      text check (char_length(terms_version) <= 20),
  is_deleted         boolean not null default false,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index profiles_platform_role_idx on public.profiles (platform_role) where platform_role <> 'user';

-- -----------------------------------------------------------------------------
-- Messes (tenants) + settings + rooms
-- -----------------------------------------------------------------------------
create table public.messes (
  id              uuid primary key default gen_random_uuid(),
  name            text not null check (char_length(name) between 3 and 80),
  description     text check (char_length(description) <= 500),
  area_id         smallint references public.areas (id) on delete set null,
  address         text check (char_length(address) <= 200),
  building_name   text check (char_length(building_name) <= 80),
  gender_policy   public.gender_pref not null default 'any',
  invite_code     text not null unique default private.new_invite_code() check (invite_code ~ '^[A-Z0-9]{8}$'),
  invite_enabled  boolean not null default true,
  is_active       boolean not null default true,
  created_by      uuid references public.profiles (id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now()
);
create index messes_area_idx on public.messes (area_id);

create table public.mess_settings (
  mess_id                    uuid primary key references public.messes (id) on delete cascade,
  meal_rate_mode             public.meal_rate_mode not null default 'auto',
  breakfast_price            numeric(10,2) not null default 35 check (breakfast_price >= 0),
  lunch_price                numeric(10,2) not null default 75 check (lunch_price >= 0),
  dinner_price               numeric(10,2) not null default 75 check (dinner_price >= 0),
  -- meal units used for the auto meal rate (breakfast often counts as half a meal)
  breakfast_weight           numeric(3,2) not null default 0.5 check (breakfast_weight between 0 and 2),
  lunch_weight               numeric(3,2) not null default 1 check (lunch_weight between 0 and 2),
  dinner_weight              numeric(3,2) not null default 1 check (dinner_weight between 0 and 2),
  breakfast_cutoff           time not null default '22:00',
  breakfast_cutoff_prev_day  boolean not null default true,
  lunch_cutoff               time not null default '10:00',
  lunch_cutoff_prev_day      boolean not null default false,
  dinner_cutoff              time not null default '17:00',
  dinner_cutoff_prev_day     boolean not null default false,
  guest_meal_allowed         boolean not null default true,
  max_guests_per_meal        smallint not null default 3 check (max_guests_per_meal between 0 and 10),
  credit_limit               numeric(10,2) not null default 0 check (credit_limit >= 0),
  low_balance_threshold      numeric(10,2) not null default 300 check (low_balance_threshold >= 0),
  split_shared_expenses      boolean not null default true,
  auto_close_enabled         boolean not null default true,
  -- previous month auto-closes on this day of the new month (grace days for late bazar slips)
  auto_close_day             smallint not null default 3 check (auto_close_day between 1 and 10),
  updated_at                 timestamptz not null default now()
);

create table public.mess_rooms (
  id            uuid primary key default gen_random_uuid(),
  mess_id       uuid not null references public.messes (id) on delete cascade,
  building      text check (char_length(building) <= 60),
  flat          text check (char_length(flat) <= 30),
  room_label    text not null check (char_length(room_label) between 1 and 30),
  room_type     public.room_type not null default 'shared',
  capacity      smallint not null default 2 check (capacity between 1 and 20),
  monthly_rent  numeric(10,2) not null default 0 check (monthly_rent >= 0),
  notes         text check (char_length(notes) <= 200),
  created_at    timestamptz not null default now(),
  unique nulls not distinct (mess_id, building, flat, room_label)
);
create index mess_rooms_mess_idx on public.mess_rooms (mess_id);

create table public.mess_members (
  id             uuid primary key default gen_random_uuid(),
  mess_id        uuid not null references public.messes (id) on delete cascade,
  user_id        uuid not null references public.profiles (id) on delete restrict,
  role           public.mess_role not null default 'member',
  status         public.member_status not null default 'pending',
  room_id        uuid references public.mess_rooms (id) on delete set null,
  seat_label     text check (char_length(seat_label) <= 20),
  request_note   text check (char_length(request_note) <= 300),
  decided_by     uuid references public.profiles (id) on delete set null,
  decided_at     timestamptz,
  decision_note  text check (char_length(decision_note) <= 300),
  joined_at      timestamptz,
  left_at        timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now(),
  constraint mess_members_joined_when_active check (status not in ('active', 'inactive') or joined_at is not null)
);
-- One open membership per user across the whole platform.
create unique index mess_members_one_open_per_user on public.mess_members (user_id)
  where status in ('pending', 'active', 'inactive');
create index mess_members_mess_status_idx on public.mess_members (mess_id, status);
create index mess_members_room_idx on public.mess_members (room_id);

-- -----------------------------------------------------------------------------
-- Platform tables
-- -----------------------------------------------------------------------------
create table public.notifications (
  id          uuid primary key default gen_random_uuid(),
  user_id     uuid not null references public.profiles (id) on delete cascade,
  mess_id     uuid references public.messes (id) on delete cascade,
  type        text not null check (char_length(type) <= 40),
  title       text not null check (char_length(title) <= 140),
  body        text check (char_length(body) <= 500),
  link        text check (char_length(link) <= 200),
  data        jsonb not null default '{}'::jsonb,
  read_at     timestamptz,
  created_at  timestamptz not null default now()
);
create index notifications_user_created_idx on public.notifications (user_id, created_at desc);
create index notifications_user_unread_idx on public.notifications (user_id) where read_at is null;

create table public.audit_logs (
  id          bigint generated always as identity primary key,
  mess_id     uuid,
  actor_id    uuid,
  action      text not null,
  table_name  text not null,
  record_id   text,
  old_data    jsonb,
  new_data    jsonb,
  created_at  timestamptz not null default now()
);
create index audit_logs_mess_created_idx on public.audit_logs (mess_id, created_at desc);
create index audit_logs_created_idx on public.audit_logs (created_at desc);

create table public.legal_acceptances (
  id           uuid primary key default gen_random_uuid(),
  user_id      uuid not null references public.profiles (id) on delete cascade,
  document     text not null check (document in ('terms', 'privacy')),
  version      text not null check (char_length(version) <= 20),
  accepted_at  timestamptz not null default now(),
  unique (user_id, document, version)
);

create table public.feedback (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid references public.profiles (id) on delete set null,
  mess_id        uuid references public.messes (id) on delete set null,
  type           public.feedback_type not null default 'feedback',
  subject        text check (char_length(subject) <= 120),
  message        text not null check (char_length(message) between 5 and 2000),
  contact_email  text check (contact_email ~* '^[^@\s]+@[^@\s]+\.[^@\s]+$'),
  page_url       text check (char_length(page_url) <= 300),
  status         public.feedback_status not null default 'new',
  admin_note     text check (char_length(admin_note) <= 1000),
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);
create index feedback_status_idx on public.feedback (status, created_at desc);

-- Fixed-window rate limiter (lives in the private schema: never exposed).
create table private.rate_limits (
  key           text primary key,
  window_start  timestamptz not null,
  hits          integer not null
);

-- -----------------------------------------------------------------------------
-- Tenancy helpers (used by RLS policies and RPCs)
-- -----------------------------------------------------------------------------

-- The mess the current user belongs to (active or temporarily inactive).
create or replace function private.current_mess_id()
returns uuid
language sql stable security definer
set search_path = ''
as $$
  select mm.mess_id
  from public.mess_members mm
  where mm.user_id = auth.uid()
    and mm.status in ('active', 'inactive')
  limit 1
$$;

-- The mess the current user manages (active managers only).
create or replace function private.managed_mess_id()
returns uuid
language sql stable security definer
set search_path = ''
as $$
  select mm.mess_id
  from public.mess_members mm
  where mm.user_id = auth.uid()
    and mm.status = 'active'
    and mm.role = 'manager'
  limit 1
$$;

create or replace function private.is_super_admin()
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.profiles p
    where p.id = auth.uid() and p.platform_role = 'super_admin' and not p.is_deleted
  )
$$;

create or replace function private.is_active_member(p_mess uuid, p_user uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.mess_members mm
    where mm.mess_id = p_mess and mm.user_id = p_user and mm.status = 'active'
  )
$$;

-- True when the current user shares a mess with p_user (used by Care contacts).
create or replace function private.shares_mess(p_user uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.mess_members mm
    where mm.user_id = p_user
      and mm.status in ('active', 'inactive')
      and mm.mess_id = private.current_mess_id()
  )
$$;

-- Profile visibility: yourself, your messmates, applicants to the mess you
-- manage, and super admins.
create or replace function private.can_view_profile(p_user uuid)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select p_user = auth.uid()
      or exists (
           select 1 from public.mess_members mm
           where mm.user_id = p_user
             and mm.mess_id = private.current_mess_id()
             and (mm.status in ('active', 'inactive')
                  or (mm.status = 'pending' and mm.mess_id = private.managed_mess_id()))
         )
      or private.is_super_admin()
$$;

-- Raises 'rate_limited' when p_key was used more than p_max times in p_window.
create or replace function private.check_rate_limit(p_key text, p_max integer, p_window interval)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  v_hits integer;
begin
  insert into private.rate_limits as rl (key, window_start, hits)
  values (p_key, now(), 1)
  on conflict (key) do update
    set hits = case when rl.window_start < now() - p_window then 1 else rl.hits + 1 end,
        window_start = case when rl.window_start < now() - p_window then now() else rl.window_start end
  returning rl.hits into v_hits;

  if v_hits > p_max then
    raise exception 'rate_limited' using hint = 'Too many requests. Try again later.';
  end if;
end;
$$;

create or replace function private.require_user()
returns uuid
language plpgsql stable
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then
    raise exception 'not_authenticated';
  end if;
  return v_uid;
end;
$$;

-- -----------------------------------------------------------------------------
-- Notification helpers
-- -----------------------------------------------------------------------------
create or replace function private.notify(
  p_user uuid, p_mess uuid, p_type text, p_title text,
  p_body text default null, p_link text default null, p_data jsonb default '{}'::jsonb
)
returns void
language sql security definer
set search_path = ''
as $$
  insert into public.notifications (user_id, mess_id, type, title, body, link, data)
  values (p_user, p_mess, p_type, left(p_title, 140), left(p_body, 500), p_link, coalesce(p_data, '{}'::jsonb));
$$;

create or replace function private.notify_managers(
  p_mess uuid, p_type text, p_title text,
  p_body text default null, p_link text default null, p_data jsonb default '{}'::jsonb
)
returns void
language sql security definer
set search_path = ''
as $$
  insert into public.notifications (user_id, mess_id, type, title, body, link, data)
  select mm.user_id, p_mess, p_type, left(p_title, 140), left(p_body, 500), p_link, coalesce(p_data, '{}'::jsonb)
  from public.mess_members mm
  where mm.mess_id = p_mess and mm.role = 'manager' and mm.status = 'active';
$$;

create or replace function private.notify_mess(
  p_mess uuid, p_type text, p_title text,
  p_body text default null, p_link text default null, p_data jsonb default '{}'::jsonb,
  p_exclude uuid default null
)
returns void
language sql security definer
set search_path = ''
as $$
  insert into public.notifications (user_id, mess_id, type, title, body, link, data)
  select mm.user_id, p_mess, p_type, left(p_title, 140), left(p_body, 500), p_link, coalesce(p_data, '{}'::jsonb)
  from public.mess_members mm
  where mm.mess_id = p_mess
    and mm.status in ('active', 'inactive')
    and mm.user_id is distinct from p_exclude;
$$;

create or replace function private.display_name(p_user uuid)
returns text
language sql stable security definer
set search_path = ''
as $$
  select coalesce(nullif(p.full_name, ''), 'সদস্য') from public.profiles p where p.id = p_user
$$;

-- -----------------------------------------------------------------------------
-- Audit trail (generic row trigger; attached to money/membership tables)
-- -----------------------------------------------------------------------------
create or replace function private.audit_row()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  v_new jsonb;
  v_old jsonb;
  v_row jsonb;
  v_mess uuid;
begin
  if tg_op in ('INSERT', 'UPDATE') then v_new := to_jsonb(new); end if;
  if tg_op in ('UPDATE', 'DELETE') then v_old := to_jsonb(old); end if;
  if tg_op = 'UPDATE' and v_new = v_old then
    return null;
  end if;
  v_row := coalesce(v_new, v_old);
  v_mess := case when tg_table_name = 'messes'
                 then private.try_uuid(v_row ->> 'id')
                 else private.try_uuid(v_row ->> 'mess_id') end;

  insert into public.audit_logs (mess_id, actor_id, action, table_name, record_id, old_data, new_data)
  values (v_mess, auth.uid(), tg_op, tg_table_name,
          coalesce(v_row ->> 'id', v_row ->> 'mess_id'), v_old, v_new);
  return null;
end;
$$;

-- -----------------------------------------------------------------------------
-- Auth integration: create the profile row when someone signs up
-- -----------------------------------------------------------------------------
create or replace function private.handle_new_user()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  v_meta  jsonb := coalesce(new.raw_user_meta_data, '{}'::jsonb);
  v_terms text := left(nullif(trim(v_meta ->> 'terms_version'), ''), 20);
  v_role  public.platform_role := 'user';
begin
  -- Self-chosen account types; super_admin can never come from metadata.
  if v_meta ->> 'account_type' in ('landlord', 'service_provider') then
    v_role := (v_meta ->> 'account_type')::public.platform_role;
  end if;

  insert into public.profiles (id, full_name, email, phone, avatar_url, platform_role,
                               preferred_locale, terms_accepted_at, terms_version)
  values (
    new.id,
    left(coalesce(nullif(trim(v_meta ->> 'full_name'), ''),
                  nullif(trim(v_meta ->> 'name'), ''),
                  split_part(coalesce(new.email, ''), '@', 1)), 80),
    new.email,
    case when v_meta ->> 'phone' ~ '^\+?[0-9]{10,14}$' then v_meta ->> 'phone' end,
    left(nullif(v_meta ->> 'avatar_url', ''), 500),
    v_role,
    case when v_meta ->> 'locale' = 'en' then 'en' else 'bn' end,
    case when v_terms is not null then now() end,
    v_terms
  )
  on conflict (id) do nothing;

  if v_terms is not null then
    insert into public.legal_acceptances (user_id, document, version)
    values (new.id, 'terms', v_terms), (new.id, 'privacy', v_terms)
    on conflict do nothing;
  end if;
  return new;
end;
$$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function private.handle_new_user();

create or replace function private.handle_user_email_change()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  update public.profiles set email = new.email where id = new.id;
  return new;
end;
$$;

create trigger on_auth_user_email_changed
  after update of email on auth.users
  for each row when (old.email is distinct from new.email)
  execute function private.handle_user_email_change();

-- Users may edit their own profile, but never their id, email, deletion flag,
-- legal acceptance or (to / from) super_admin role.
create or replace function private.guard_profile_update()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if private.is_system_call() or private.is_internal() then
    return new;
  end if;

  new.id := old.id;
  new.email := old.email;
  new.created_at := old.created_at;
  new.is_deleted := old.is_deleted;
  new.terms_accepted_at := old.terms_accepted_at;
  new.terms_version := old.terms_version;

  if new.platform_role is distinct from old.platform_role and not private.is_super_admin() then
    if new.platform_role = 'super_admin' or old.platform_role = 'super_admin' then
      raise exception 'forbidden_role_change';
    end if;
  end if;
  return new;
end;
$$;

create trigger profiles_guard before update on public.profiles
  for each row execute function private.guard_profile_update();
create trigger profiles_updated_at before update on public.profiles
  for each row execute function private.set_updated_at();

-- Managers edit their mess details; ownership, activation and invite codes are
-- changed only through RPCs or by super admins.
create or replace function private.guard_mess_update()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if private.is_system_call() or private.is_internal() or private.is_super_admin() then
    return new;
  end if;
  new.id := old.id;
  new.created_by := old.created_by;
  new.created_at := old.created_at;
  new.is_active := old.is_active;
  new.invite_code := old.invite_code;
  return new;
end;
$$;

create trigger messes_guard before update on public.messes
  for each row execute function private.guard_mess_update();
create trigger messes_updated_at before update on public.messes
  for each row execute function private.set_updated_at();
create trigger mess_settings_updated_at before update on public.mess_settings
  for each row execute function private.set_updated_at();
create trigger mess_members_updated_at before update on public.mess_members
  for each row execute function private.set_updated_at();
create trigger feedback_updated_at before update on public.feedback
  for each row execute function private.set_updated_at();

create trigger messes_audit after insert or update or delete on public.messes
  for each row execute function private.audit_row();
create trigger mess_settings_audit after insert or update on public.mess_settings
  for each row execute function private.audit_row();
create trigger mess_members_audit after insert or update or delete on public.mess_members
  for each row execute function private.audit_row();

-- Rooms belong to one mess; a member can only be placed in a room of their mess.
create or replace function private.check_member_room()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if new.room_id is not null and not exists (
    select 1 from public.mess_rooms r where r.id = new.room_id and r.mess_id = new.mess_id
  ) then
    raise exception 'room_not_in_mess';
  end if;
  return new;
end;
$$;

create trigger mess_members_room_check before insert or update of room_id on public.mess_members
  for each row execute function private.check_member_room();

-- =============================================================================
-- Core RPCs (called from Next.js server actions with the user's session)
-- =============================================================================

create or replace function private.require_terms(p_uid uuid)
returns void
language plpgsql stable security definer
set search_path = ''
as $$
begin
  if not exists (select 1 from public.profiles p where p.id = p_uid and p.terms_accepted_at is not null) then
    raise exception 'terms_not_accepted';
  end if;
end;
$$;

-- Create a mess; the caller becomes its first manager.
create or replace function public.create_mess(
  p_name           text,
  p_area_id        integer default null,
  p_address        text default null,
  p_building_name  text default null,
  p_description    text default null,
  p_meal_rate_mode public.meal_rate_mode default 'auto',
  p_gender_policy  public.gender_pref default 'any'
)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid  uuid := private.require_user();
  v_mess uuid;
begin
  perform private.require_terms(v_uid);
  perform private.check_rate_limit('create_mess:' || v_uid, 3, interval '1 day');

  if exists (select 1 from public.mess_members
             where user_id = v_uid and status in ('pending', 'active', 'inactive')) then
    raise exception 'already_in_mess';
  end if;

  insert into public.messes (name, description, area_id, address, building_name, gender_policy, created_by)
  values (trim(p_name), nullif(trim(p_description), ''), p_area_id::smallint,
          nullif(trim(p_address), ''), nullif(trim(p_building_name), ''), p_gender_policy, v_uid)
  returning id into v_mess;

  insert into public.mess_settings (mess_id, meal_rate_mode) values (v_mess, p_meal_rate_mode);

  insert into public.mess_members (mess_id, user_id, role, status, joined_at, decided_by, decided_at)
  values (v_mess, v_uid, 'manager', 'active', now(), v_uid, now());

  return v_mess;
end;
$$;

create or replace function public.regenerate_invite_code(p_mess_id uuid)
returns text
language plpgsql security definer
set search_path = ''
as $$
declare
  v_code text;
begin
  perform private.require_user();
  if private.managed_mess_id() is distinct from p_mess_id then
    raise exception 'not_manager';
  end if;

  perform private.set_internal(true);
  loop
    v_code := private.new_invite_code();
    begin
      update public.messes set invite_code = v_code where id = p_mess_id;
      exit;
    exception when unique_violation then
      -- extremely unlikely collision: try another code
    end;
  end loop;
  perform private.set_internal(false);
  return v_code;
end;
$$;

-- Minimal public card for the join page (non-members cannot read messes).
create or replace function public.get_mess_by_invite(p_code text)
returns table (
  mess_id        uuid,
  name           text,
  area_name_bn   text,
  area_name_en   text,
  address        text,
  gender_policy  public.gender_pref,
  member_count   bigint,
  invite_enabled boolean
)
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
begin
  perform private.check_rate_limit('invite_lookup:' || v_uid, 30, interval '10 minutes');
  return query
    select m.id, m.name, a.name_bn, a.name_en, m.address, m.gender_policy,
           (select count(*) from public.mess_members mm where mm.mess_id = m.id and mm.status = 'active'),
           m.invite_enabled
    from public.messes m
    left join public.areas a on a.id = m.area_id
    where m.invite_code = upper(trim(p_code)) and m.is_active;
end;
$$;

create or replace function public.request_join(p_code text, p_note text default null)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid  uuid := private.require_user();
  v_mess public.messes%rowtype;
  v_id   uuid;
begin
  perform private.require_terms(v_uid);
  perform private.check_rate_limit('join:' || v_uid, 10, interval '1 hour');

  select * into v_mess from public.messes where invite_code = upper(trim(p_code)) and is_active;
  if not found then
    raise exception 'invalid_invite';
  end if;
  if not v_mess.invite_enabled then
    raise exception 'invite_disabled';
  end if;
  if exists (select 1 from public.mess_members
             where user_id = v_uid and status in ('pending', 'active', 'inactive')) then
    raise exception 'already_in_mess';
  end if;

  insert into public.mess_members (mess_id, user_id, role, status, request_note)
  values (v_mess.id, v_uid, 'member', 'pending', left(nullif(trim(p_note), ''), 300))
  returning id into v_id;

  perform private.notify_managers(
    v_mess.id, 'join_request', 'নতুন সদস্যের অনুরোধ',
    private.display_name(v_uid) || ' মেসে যোগ দিতে চায়।', '/manage/members',
    jsonb_build_object('membership_id', v_id, 'user_id', v_uid));
  return v_id;
end;
$$;

create or replace function public.cancel_join_request()
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
begin
  delete from public.mess_members where user_id = v_uid and status = 'pending';
  if not found then
    raise exception 'no_pending_request';
  end if;
end;
$$;

create or replace function public.decide_join_request(p_membership_id uuid, p_approve boolean, p_note text default null)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_row public.mess_members%rowtype;
begin
  select * into v_row from public.mess_members where id = p_membership_id for update;
  if not found then
    raise exception 'not_found';
  end if;
  if private.managed_mess_id() is distinct from v_row.mess_id then
    raise exception 'not_manager';
  end if;
  if v_row.status <> 'pending' then
    raise exception 'not_pending';
  end if;

  update public.mess_members
     set status = case when p_approve then 'active'::public.member_status else 'rejected'::public.member_status end,
         joined_at = case when p_approve then now() else null end,
         decided_by = v_uid,
         decided_at = now(),
         decision_note = left(nullif(trim(p_note), ''), 300)
   where id = p_membership_id;

  if p_approve then
    perform private.notify(v_row.user_id, v_row.mess_id, 'join_approved',
      'মেসে স্বাগতম!', 'আপনার যোগদানের অনুরোধ অনুমোদিত হয়েছে।', '/dashboard');
  else
    perform private.notify(v_row.user_id, null, 'join_rejected',
      'যোগদানের অনুরোধ গৃহীত হয়নি', coalesce(nullif(trim(p_note), ''), 'ম্যানেজার অনুরোধটি বাতিল করেছেন।'), '/onboarding');
  end if;
end;
$$;

create or replace function public.leave_mess()
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_row public.mess_members%rowtype;
  v_balance numeric;
begin
  select * into v_row from public.mess_members
   where user_id = v_uid and status in ('active', 'inactive') for update;
  if not found then
    raise exception 'not_in_mess';
  end if;

  if v_row.role = 'manager'
     and not exists (select 1 from public.mess_members
                     where mess_id = v_row.mess_id and role = 'manager' and status = 'active' and id <> v_row.id)
     and exists (select 1 from public.mess_members
                 where mess_id = v_row.mess_id and status in ('active', 'inactive') and id <> v_row.id) then
    raise exception 'last_manager';
  end if;

  update public.mess_members set status = 'left', left_at = now(), room_id = null where id = v_row.id;

  -- Last person out: deactivate the mess.
  if not exists (select 1 from public.mess_members where mess_id = v_row.mess_id and status in ('active', 'inactive')) then
    perform private.set_internal(true);
    update public.messes set is_active = false, invite_enabled = false where id = v_row.mess_id;
    perform private.set_internal(false);
  end if;

  select coalesce(sum(amount), 0) into v_balance
    from public.ledger_entries where mess_id = v_row.mess_id and user_id = v_uid;

  perform private.notify_managers(v_row.mess_id, 'member_left', 'একজন সদস্য মেস ছেড়েছেন',
    private.display_name(v_uid) || ' মেস ছেড়েছেন। হিসাবের ব্যালেন্স: ' || private.taka(v_balance),
    '/manage/members', jsonb_build_object('user_id', v_uid, 'balance', v_balance));
end;
$$;

-- Manager changes a member's role, status (active / inactive / left) or room.
create or replace function public.update_member(
  p_membership_id uuid,
  p_role          public.mess_role default null,
  p_status        public.member_status default null,
  p_room_id       uuid default null,
  p_seat_label    text default null,
  p_clear_room    boolean default false
)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_row public.mess_members%rowtype;
  v_room public.mess_rooms%rowtype;
  v_losing_manager boolean;
begin
  select * into v_row from public.mess_members where id = p_membership_id for update;
  if not found then
    raise exception 'not_found';
  end if;
  if private.managed_mess_id() is distinct from v_row.mess_id then
    raise exception 'not_manager';
  end if;
  if v_row.status not in ('active', 'inactive') then
    raise exception 'not_member';
  end if;
  if p_status is not null and p_status not in ('active', 'inactive', 'left') then
    raise exception 'invalid_status';
  end if;

  v_losing_manager := v_row.role = 'manager'
    and (p_role = 'member' or p_status in ('inactive', 'left'));
  if v_losing_manager and not exists (
       select 1 from public.mess_members
       where mess_id = v_row.mess_id and role = 'manager' and status = 'active' and id <> v_row.id) then
    raise exception 'last_manager';
  end if;

  if p_room_id is not null then
    select * into v_room from public.mess_rooms where id = p_room_id and mess_id = v_row.mess_id;
    if not found then
      raise exception 'room_not_in_mess';
    end if;
    if (select count(*) from public.mess_members
        where room_id = p_room_id and status in ('active', 'inactive') and id <> v_row.id) >= v_room.capacity then
      raise exception 'room_full';
    end if;
  end if;

  update public.mess_members
     set role = coalesce(p_role, role),
         status = coalesce(p_status, status),
         left_at = case when p_status = 'left' then now() else left_at end,
         room_id = case when p_clear_room or p_status = 'left' then null
                        when p_room_id is not null then p_room_id
                        else room_id end,
         seat_label = case when p_seat_label is not null then left(nullif(trim(p_seat_label), ''), 20) else seat_label end
   where id = v_row.id;

  if p_status = 'left' then
    perform private.notify(v_row.user_id, null, 'removed_from_mess', 'আপনাকে মেস থেকে সরানো হয়েছে',
      'ম্যানেজার আপনার সদস্যপদ বন্ধ করেছেন। হিসাব জানতে ম্যানেজারের সাথে যোগাযোগ করুন।', '/onboarding');
  elsif p_role is not null and p_role <> v_row.role then
    perform private.notify(v_row.user_id, v_row.mess_id, 'role_changed',
      case when p_role = 'manager' then 'আপনি এখন ম্যানেজার' else 'আপনার ম্যানেজার দায়িত্ব শেষ' end,
      null, '/dashboard');
  end if;
end;
$$;

create or replace function public.accept_legal(p_version text)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_version text := left(nullif(trim(p_version), ''), 20);
begin
  if v_version is null then
    raise exception 'invalid_version';
  end if;
  insert into public.legal_acceptances (user_id, document, version)
  values (v_uid, 'terms', v_version), (v_uid, 'privacy', v_version)
  on conflict do nothing;

  perform private.set_internal(true);
  update public.profiles set terms_accepted_at = now(), terms_version = v_version where id = v_uid;
  perform private.set_internal(false);
end;
$$;

create or replace function public.mark_notifications_read(p_ids uuid[] default null)
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  v_count integer;
begin
  update public.notifications
     set read_at = now()
   where user_id = v_uid and read_at is null
     and (p_ids is null or id = any (p_ids));
  get diagnostics v_count = row_count;
  return v_count;
end;
$$;

-- Feedback / contact / bug report. Anonymous visitors share a global limit.
create or replace function public.submit_feedback(
  p_type          public.feedback_type,
  p_message       text,
  p_subject       text default null,
  p_contact_email text default null,
  p_page_url      text default null
)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid uuid := auth.uid();
  v_id  uuid;
begin
  if v_uid is null then
    perform private.check_rate_limit('feedback:anon', 30, interval '1 hour');
  else
    perform private.check_rate_limit('feedback:' || v_uid, 10, interval '1 hour');
  end if;

  insert into public.feedback (user_id, mess_id, type, subject, message, contact_email, page_url)
  values (v_uid, case when v_uid is not null then private.current_mess_id() end, p_type,
          left(nullif(trim(p_subject), ''), 120), trim(p_message),
          nullif(trim(p_contact_email), ''), left(nullif(trim(p_page_url), ''), 300))
  returning id into v_id;
  return v_id;
end;
$$;

-- Display names + avatars for a set of users (marketplace sellers, reviewers,
-- organisers). Takes ids so the whole user list cannot be enumerated.
create or replace function public.get_public_profiles(p_ids uuid[])
returns table (id uuid, full_name text, avatar_url text)
language plpgsql stable security definer
set search_path = ''
as $$
begin
  perform private.require_user();
  if cardinality(p_ids) > 200 then
    raise exception 'too_many_ids';
  end if;
  return query
    select p.id, p.full_name, p.avatar_url
    from public.profiles p
    where p.id = any (p_ids) and not p.is_deleted;
end;
$$;


-- >>> 0003_wallet.sql
-- =============================================================================
-- MessMate BD · 0003 · Wallet (immutable ledger) + month locks + deposits
--
-- A member's balance is ALWAYS sum(ledger_entries.amount). Entries are never
-- edited or deleted: mistakes are fixed with a reversal entry. Positive amount =
-- money credited to the member, negative = money charged.
--
-- The app does not move real money. Members pay the manager by bKash / Nagad /
-- Rocket / cash and submit the TrxID; the manager confirms it by hand.
-- =============================================================================

-- Month closings lock a period: no ledger entry, menu, order, expense or bill can
-- be added to a closed month. (Closing logic lives in 0005.)
create table public.monthly_closings (
  id                    uuid primary key default gen_random_uuid(),
  mess_id               uuid not null references public.messes (id) on delete cascade,
  period_month          date not null check (period_month = date_trunc('month', period_month::timestamp)::date),
  meal_rate_mode        public.meal_rate_mode not null,
  total_meal_units      numeric(12,2) not null default 0,
  total_meal_expense    numeric(12,2) not null default 0,
  meal_rate             numeric(12,4) not null default 0,
  total_shared_expense  numeric(12,2) not null default 0,
  total_bills           numeric(12,2) not null default 0,
  total_deposits        numeric(12,2) not null default 0,
  member_count          integer not null default 0,
  closed_by             uuid references public.profiles (id) on delete set null,
  closed_at             timestamptz not null default now(),
  notes                 text check (char_length(notes) <= 500),
  unique (mess_id, period_month)
);

create or replace function private.is_month_closed(p_mess uuid, p_date date)
returns boolean
language sql stable security definer
set search_path = ''
as $$
  select exists (
    select 1 from public.monthly_closings c
    where c.mess_id = p_mess and c.period_month = private.month_start(p_date)
  )
$$;

-- -----------------------------------------------------------------------------
-- Ledger
-- -----------------------------------------------------------------------------
create table public.ledger_entries (
  id            uuid primary key default gen_random_uuid(),
  mess_id       uuid not null references public.messes (id) on delete restrict,
  user_id       uuid not null references public.profiles (id) on delete restrict,
  entry_type    public.ledger_type not null,
  amount        numeric(12,2) not null check (amount <> 0 and abs(amount) <= 10000000),
  description   text check (char_length(description) <= 200),
  period_month  date not null default private.month_start(private.dhaka_today())
                check (period_month = date_trunc('month', period_month::timestamp)::date),
  ref_table     text check (ref_table in ('deposit_requests', 'meal_orders', 'bill_shares', 'expenses', 'monthly_closings')),
  ref_id        uuid,
  reverses_id   uuid unique references public.ledger_entries (id) on delete restrict,
  created_by    uuid references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  constraint ledger_sign_matches_type check (
       (entry_type in ('deposit', 'meal_refund', 'reimbursement') and amount > 0)
    or (entry_type in ('meal_charge', 'bill_share', 'refund_payout') and amount < 0)
    or (entry_type in ('adjustment', 'reversal'))
  ),
  constraint ledger_reversal_link check ((entry_type = 'reversal') = (reverses_id is not null))
);
create index ledger_mess_user_period_idx on public.ledger_entries (mess_id, user_id, period_month);
create index ledger_mess_period_idx on public.ledger_entries (mess_id, period_month, entry_type);
create index ledger_user_idx on public.ledger_entries (user_id, created_at desc);
create index ledger_ref_idx on public.ledger_entries (ref_table, ref_id);

-- Append-only: block UPDATE / DELETE, and block inserts into a closed month.
create or replace function private.ledger_guard()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  if tg_op = 'INSERT' then
    if private.is_month_closed(new.mess_id, new.period_month) then
      raise exception 'month_closed';
    end if;
    return new;
  end if;

  if private.is_purge() then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  raise exception 'ledger_immutable' using hint = 'Ledger entries cannot be changed. Post a reversal instead.';
end;
$$;

create trigger ledger_entries_guard
  before insert or update or delete on public.ledger_entries
  for each row execute function private.ledger_guard();

-- Low-balance alert when a charge pushes the balance below the mess threshold.
create or replace function private.ledger_low_balance()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  v_threshold numeric;
  v_balance numeric;
begin
  if new.amount >= 0 then
    return null;
  end if;
  select s.low_balance_threshold into v_threshold from public.mess_settings s where s.mess_id = new.mess_id;
  if coalesce(v_threshold, 0) = 0 then
    return null;
  end if;
  select coalesce(sum(l.amount), 0) into v_balance
    from public.ledger_entries l where l.mess_id = new.mess_id and l.user_id = new.user_id;
  if v_balance < v_threshold and v_balance - new.amount >= v_threshold then
    perform private.notify(new.user_id, new.mess_id, 'low_balance', 'ব্যালেন্স কমে গেছে',
      'আপনার বর্তমান ব্যালেন্স ' || private.taka(v_balance) || '। মিল চালু রাখতে টাকা যোগ করুন।',
      '/wallet', jsonb_build_object('balance', v_balance, 'threshold', v_threshold));
  end if;
  return null;
end;
$$;

create trigger ledger_entries_low_balance
  after insert on public.ledger_entries
  for each row execute function private.ledger_low_balance();

create trigger ledger_entries_audit
  after insert on public.ledger_entries
  for each row execute function private.audit_row();

-- Balances (security_invoker: the caller's RLS applies — members see their own
-- row, managers see every member of their mess).
create view public.member_balances
with (security_invoker = true)
as
select l.mess_id,
       l.user_id,
       sum(l.amount)                                                        as balance,
       coalesce(sum(l.amount) filter (where l.entry_type = 'deposit'), 0)    as total_deposits,
       coalesce(sum(l.amount) filter (where l.entry_type = 'deposit'), 0) - sum(l.amount) as total_spent,
       max(l.created_at)                                                    as last_activity_at
from public.ledger_entries l
group by l.mess_id, l.user_id;

create or replace function private.balance_of(p_mess uuid, p_user uuid)
returns numeric
language sql stable security definer
set search_path = ''
as $$
  select coalesce(sum(l.amount), 0)::numeric
  from public.ledger_entries l
  where l.mess_id = p_mess and l.user_id = p_user
$$;

-- -----------------------------------------------------------------------------
-- Deposit requests (manual TrxID verification)
-- -----------------------------------------------------------------------------
create table public.deposit_requests (
  id               uuid primary key default gen_random_uuid(),
  mess_id          uuid not null references public.messes (id) on delete restrict,
  user_id          uuid not null references public.profiles (id) on delete restrict,
  amount           numeric(12,2) not null check (amount >= 10 and amount <= 100000),
  method           public.payment_method not null,
  trx_id           text check (trx_id ~ '^[A-Z0-9]{6,20}$'),
  sender_number    text check (sender_number ~ '^\+?[0-9]{10,14}$'),
  paid_at          timestamptz,
  note             text check (char_length(note) <= 300),
  proof_path       text check (char_length(proof_path) <= 300),
  status           public.request_status not null default 'pending',
  reviewed_by      uuid references public.profiles (id) on delete set null,
  reviewed_at      timestamptz,
  review_note      text check (char_length(review_note) <= 300),
  ledger_entry_id  uuid references public.ledger_entries (id) on delete restrict,
  created_at       timestamptz not null default now(),
  constraint deposit_trx_required check (method = 'cash' or trx_id is not null),
  constraint deposit_approved_has_entry check (status <> 'approved' or ledger_entry_id is not null)
);
-- The same transaction ID cannot be claimed twice in one mess (unless rejected).
create unique index deposit_requests_trx_unique on public.deposit_requests (mess_id, method, trx_id)
  where trx_id is not null and status <> 'rejected';
create index deposit_requests_mess_status_idx on public.deposit_requests (mess_id, status, created_at desc);
create index deposit_requests_user_idx on public.deposit_requests (user_id, created_at desc);

create trigger deposit_requests_audit
  after insert or update on public.deposit_requests
  for each row execute function private.audit_row();

-- Member submits "I sent ৳X by bKash, TrxID ABC123".
create or replace function public.submit_deposit(
  p_amount        numeric,
  p_method        public.payment_method,
  p_trx_id        text default null,
  p_sender_number text default null,
  p_paid_at       timestamptz default null,
  p_note          text default null,
  p_proof_path    text default null
)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid  uuid := private.require_user();
  v_mess uuid := private.current_mess_id();
  v_trx  text := nullif(upper(regexp_replace(coalesce(p_trx_id, ''), '\s', '', 'g')), '');
  v_id   uuid;
begin
  if v_mess is null then
    raise exception 'not_in_mess';
  end if;
  perform private.check_rate_limit('deposit:' || v_uid, 6, interval '1 hour');

  if p_amount is null or p_amount < 10 or p_amount > 100000 then
    raise exception 'invalid_amount';
  end if;
  if p_method <> 'cash' and v_trx is null then
    raise exception 'trx_id_required';
  end if;
  if v_trx is not null and v_trx !~ '^[A-Z0-9]{6,20}$' then
    raise exception 'invalid_trx_id';
  end if;
  if v_trx is not null and exists (
       select 1 from public.deposit_requests
       where mess_id = v_mess and method = p_method and trx_id = v_trx and status <> 'rejected') then
    raise exception 'duplicate_trx_id';
  end if;
  if p_proof_path is not null and p_proof_path not like v_mess::text || '/' || v_uid::text || '/%' then
    raise exception 'invalid_proof_path';
  end if;

  insert into public.deposit_requests (mess_id, user_id, amount, method, trx_id, sender_number, paid_at, note, proof_path)
  values (v_mess, v_uid, round(p_amount, 2), p_method, v_trx,
          nullif(regexp_replace(coalesce(p_sender_number, ''), '[\s-]', '', 'g'), ''),
          coalesce(p_paid_at, now()), left(nullif(trim(p_note), ''), 300), p_proof_path)
  returning id into v_id;

  perform private.notify_managers(v_mess, 'deposit_submitted', 'নতুন টাকা জমার অনুরোধ',
    private.display_name(v_uid) || ' ' || private.taka(p_amount) || ' জমা দিয়েছেন (' || p_method::text
      || coalesce(' · ' || v_trx, '') || ')। যাচাই করে অনুমোদন দিন।',
    '/manage/approvals', jsonb_build_object('request_id', v_id, 'amount', p_amount));
  return v_id;
end;
$$;

-- Manager approves (posts a ledger deposit) or rejects a request.
create or replace function public.review_deposit(p_request_id uuid, p_approve boolean, p_note text default null)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid   uuid := private.require_user();
  v_req   public.deposit_requests%rowtype;
  v_entry uuid;
begin
  select * into v_req from public.deposit_requests where id = p_request_id for update;
  if not found then
    raise exception 'not_found';
  end if;
  if private.managed_mess_id() is distinct from v_req.mess_id then
    raise exception 'not_manager';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'already_reviewed';
  end if;

  if p_approve then
    insert into public.ledger_entries (mess_id, user_id, entry_type, amount, description, ref_table, ref_id, created_by)
    values (v_req.mess_id, v_req.user_id, 'deposit', v_req.amount,
            'জমা · ' || v_req.method::text || coalesce(' · ' || v_req.trx_id, ''),
            'deposit_requests', v_req.id, v_uid)
    returning id into v_entry;

    update public.deposit_requests
       set status = 'approved', reviewed_by = v_uid, reviewed_at = now(),
           review_note = left(nullif(trim(p_note), ''), 300), ledger_entry_id = v_entry
     where id = v_req.id;

    perform private.notify(v_req.user_id, v_req.mess_id, 'deposit_approved', 'টাকা জমা হয়েছে',
      private.taka(v_req.amount) || ' আপনার ওয়ালেটে যোগ হয়েছে। নতুন ব্যালেন্স '
        || private.taka(private.balance_of(v_req.mess_id, v_req.user_id)) || '।',
      '/wallet', jsonb_build_object('request_id', v_req.id, 'amount', v_req.amount));
  else
    update public.deposit_requests
       set status = 'rejected', reviewed_by = v_uid, reviewed_at = now(),
           review_note = left(nullif(trim(p_note), ''), 300)
     where id = v_req.id;

    perform private.notify(v_req.user_id, v_req.mess_id, 'deposit_rejected', 'টাকা জমার অনুরোধ বাতিল',
      coalesce(nullif(trim(p_note), ''), 'TrxID বা পরিমাণ মেলেনি। ম্যানেজারের সাথে কথা বলুন।'),
      '/wallet', jsonb_build_object('request_id', v_req.id));
  end if;
  return v_entry;
end;
$$;

-- Manager-only entries: cash received in hand, corrections, refunds paid out.
create or replace function public.manager_ledger_entry(
  p_user_id uuid,
  p_type    public.ledger_type,
  p_amount  numeric,
  p_note    text default null
)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid    uuid := private.require_user();
  v_mess   uuid := private.managed_mess_id();
  v_amount numeric(12,2);
  v_entry  uuid;
  v_req    uuid;
  v_note   text := left(nullif(trim(p_note), ''), 200);
begin
  if v_mess is null then
    raise exception 'not_manager';
  end if;
  if not exists (select 1 from public.mess_members
                 where mess_id = v_mess and user_id = p_user_id and status in ('active', 'inactive', 'left')) then
    raise exception 'not_member';
  end if;
  if p_amount is null or p_amount = 0 or abs(p_amount) > 1000000 then
    raise exception 'invalid_amount';
  end if;

  case p_type
    when 'deposit' then
      if p_amount < 0 then raise exception 'invalid_amount'; end if;
      v_amount := round(p_amount, 2);
    when 'refund_payout' then
      v_amount := -round(abs(p_amount), 2);
    when 'adjustment' then
      if v_note is null or char_length(v_note) < 3 then raise exception 'reason_required'; end if;
      v_amount := round(p_amount, 2);
    else
      raise exception 'invalid_type';
  end case;

  if p_type = 'deposit' then
    -- keep the member's deposit history complete: record it as an approved cash request
    insert into public.deposit_requests (mess_id, user_id, amount, method, note, status, reviewed_by, reviewed_at, paid_at, ledger_entry_id)
    values (v_mess, p_user_id, v_amount, 'cash', v_note, 'pending', v_uid, now(), now(), null)
    returning id into v_req;
  end if;

  insert into public.ledger_entries (mess_id, user_id, entry_type, amount, description, ref_table, ref_id, created_by)
  values (v_mess, p_user_id, p_type, v_amount,
          coalesce(v_note, case p_type when 'deposit' then 'নগদ জমা' when 'refund_payout' then 'টাকা ফেরত' else 'সমন্বয়' end),
          case when v_req is not null then 'deposit_requests' end, v_req, v_uid)
  returning id into v_entry;

  if v_req is not null then
    update public.deposit_requests set status = 'approved', ledger_entry_id = v_entry where id = v_req;
  end if;

  perform private.notify(p_user_id, v_mess, 'ledger_' || p_type::text,
    case p_type when 'deposit' then 'নগদ টাকা জমা হয়েছে'
                when 'refund_payout' then 'টাকা ফেরত দেওয়া হয়েছে'
                else 'হিসাবে সমন্বয় করা হয়েছে' end,
    private.taka(v_amount) || coalesce(' · ' || v_note, ''), '/wallet',
    jsonb_build_object('entry_id', v_entry, 'amount', v_amount));
  return v_entry;
end;
$$;

-- Undo a deposit / adjustment / payout / reimbursement by posting its negation.
create or replace function public.reverse_ledger_entry(p_entry_id uuid, p_reason text)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid    uuid := private.require_user();
  v_entry  public.ledger_entries%rowtype;
  v_reason text := left(nullif(trim(p_reason), ''), 150);
  v_new    uuid;
begin
  select * into v_entry from public.ledger_entries where id = p_entry_id;
  if not found then
    raise exception 'not_found';
  end if;
  if private.managed_mess_id() is distinct from v_entry.mess_id then
    raise exception 'not_manager';
  end if;
  if v_entry.entry_type not in ('deposit', 'adjustment', 'refund_payout', 'reimbursement') then
    raise exception 'not_reversible';
  end if;
  if exists (select 1 from public.ledger_entries where reverses_id = v_entry.id) then
    raise exception 'already_reversed';
  end if;
  if v_reason is null or char_length(v_reason) < 3 then
    raise exception 'reason_required';
  end if;

  insert into public.ledger_entries (mess_id, user_id, entry_type, amount, description, reverses_id, created_by)
  values (v_entry.mess_id, v_entry.user_id, 'reversal', -v_entry.amount, 'বাতিল: ' || v_reason, v_entry.id, v_uid)
  returning id into v_new;

  perform private.notify(v_entry.user_id, v_entry.mess_id, 'ledger_reversal', 'একটি লেনদেন বাতিল করা হয়েছে',
    private.taka(-v_entry.amount) || ' · ' || v_reason, '/wallet', jsonb_build_object('entry_id', v_new));
  return v_new;
end;
$$;

create or replace function public.get_wallet_summary(p_user_id uuid default null)
returns jsonb
language plpgsql stable security definer
set search_path = ''
as $$
declare
  v_uid    uuid := private.require_user();
  v_mess   uuid := private.current_mess_id();
  v_target uuid := coalesce(p_user_id, v_uid);
  v_result jsonb;
begin
  if v_mess is null then
    raise exception 'not_in_mess';
  end if;
  if v_target <> v_uid and private.managed_mess_id() is distinct from v_mess then
    raise exception 'not_manager';
  end if;

  select jsonb_build_object(
           'balance',        coalesce(sum(l.amount), 0),
           'total_deposits', coalesce(sum(l.amount) filter (where l.entry_type = 'deposit'), 0),
           'total_spent',    coalesce(sum(l.amount) filter (where l.entry_type = 'deposit'), 0) - coalesce(sum(l.amount), 0),
           'pending_count',  (select count(*) from public.deposit_requests d
                               where d.mess_id = v_mess and d.user_id = v_target and d.status = 'pending'),
           'pending_amount', (select coalesce(sum(d.amount), 0) from public.deposit_requests d
                               where d.mess_id = v_mess and d.user_id = v_target and d.status = 'pending'))
    into v_result
    from public.ledger_entries l
   where l.mess_id = v_mess and l.user_id = v_target;
  return v_result;
end;
$$;


-- >>> 0004_meals.sql
-- =============================================================================
-- MessMate BD · 0004 · Daily menu + meal orders
--
-- Two billing modes (mess_settings.meal_rate_mode):
--   fixed : each order is charged the menu price immediately (prepaid wallet)
--   auto  : orders are only counted; at month close the meal rate =
--           meal expenses ÷ total meal units, and each member is charged
--           units × rate (classic Dhaka mess system)
-- =============================================================================

create table public.menus (
  id          uuid primary key default gen_random_uuid(),
  mess_id     uuid not null references public.messes (id) on delete cascade,
  menu_date   date not null,
  slot        public.meal_slot not null,
  items       text not null check (char_length(items) between 2 and 200),
  price       numeric(10,2) check (price >= 0 and price <= 2000),
  cutoff_at   timestamptz,
  is_locked   boolean not null default false,
  notes       text check (char_length(notes) <= 200),
  created_by  uuid references public.profiles (id) on delete set null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  unique (mess_id, menu_date, slot),
  unique (id, mess_id)
);
create index menus_mess_date_idx on public.menus (mess_id, menu_date);

create table public.meal_orders (
  id              uuid primary key default gen_random_uuid(),
  mess_id         uuid not null,
  menu_id         uuid not null,
  user_id         uuid not null references public.profiles (id) on delete restrict,
  status          public.order_status not null default 'ordered',
  guest_count     smallint not null default 0 check (guest_count between 0 and 10),
  charged_amount  numeric(10,2) not null default 0 check (charged_amount >= 0),
  ordered_by      uuid references public.profiles (id) on delete set null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  unique (menu_id, user_id),
  -- composite FK keeps the denormalised mess_id honest
  foreign key (menu_id, mess_id) references public.menus (id, mess_id) on delete cascade
);
create index meal_orders_mess_user_idx on public.meal_orders (mess_id, user_id);
create index meal_orders_menu_idx on public.meal_orders (menu_id, status);

-- Defaults (price + cutoff from mess settings) and month-lock / price-lock rules.
create or replace function private.menu_guard()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  s public.mess_settings%rowtype;
begin
  if tg_op = 'DELETE' then
    if private.is_purge() then
      return old;
    end if;
    if private.is_month_closed(old.mess_id, old.menu_date) then
      raise exception 'month_closed';
    end if;
    if exists (select 1 from public.meal_orders o where o.menu_id = old.id and o.status = 'ordered') then
      raise exception 'menu_has_orders';
    end if;
    return old;
  end if;

  if private.is_month_closed(new.mess_id, new.menu_date) then
    raise exception 'month_closed';
  end if;

  if tg_op = 'UPDATE' then
    if new.mess_id <> old.mess_id or new.menu_date <> old.menu_date or new.slot <> old.slot then
      raise exception 'menu_identity_locked';
    end if;
    if new.price is distinct from old.price and exists (
         select 1 from public.meal_orders o
         where o.menu_id = old.id and o.status = 'ordered' and o.charged_amount > 0) then
      raise exception 'menu_price_locked';
    end if;
  else
    new.created_by := coalesce(new.created_by, auth.uid());
  end if;

  select * into s from public.mess_settings where mess_id = new.mess_id;
  if not found then
    raise exception 'mess_settings_missing';
  end if;

  if new.price is null then
    new.price := case new.slot when 'breakfast' then s.breakfast_price
                               when 'lunch' then s.lunch_price
                               else s.dinner_price end;
  end if;
  if new.cutoff_at is null then
    new.cutoff_at := case new.slot
      when 'breakfast' then private.dhaka_ts(new.menu_date - case when s.breakfast_cutoff_prev_day then 1 else 0 end, s.breakfast_cutoff)
      when 'lunch'     then private.dhaka_ts(new.menu_date - case when s.lunch_cutoff_prev_day then 1 else 0 end, s.lunch_cutoff)
      else                  private.dhaka_ts(new.menu_date - case when s.dinner_cutoff_prev_day then 1 else 0 end, s.dinner_cutoff)
    end;
  end if;
  return new;
end;
$$;

create trigger menus_guard before insert or update or delete on public.menus
  for each row execute function private.menu_guard();
create trigger menus_updated_at before update on public.menus
  for each row execute function private.set_updated_at();

-- Orders of a closed month are frozen (their units fed the meal rate).
create or replace function private.meal_order_guard()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  v_menu_date date;
  v_mess uuid;
begin
  if private.is_purge() then
    return case when tg_op = 'DELETE' then old else new end;
  end if;
  select m.menu_date, m.mess_id into v_menu_date, v_mess
    from public.menus m where m.id = coalesce(new.menu_id, old.menu_id);
  if v_menu_date is not null and private.is_month_closed(v_mess, v_menu_date) then
    raise exception 'month_closed';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;

create trigger meal_orders_guard before insert or update or delete on public.meal_orders
  for each row execute function private.meal_order_guard();
create trigger meal_orders_updated_at before update on public.meal_orders
  for each row execute function private.set_updated_at();

-- -----------------------------------------------------------------------------
-- Order / cancel / guest meals — one idempotent call for every toggle in the UI.
--   p_ordered = false cancels. Managers may act for a member and ignore cutoff.
-- -----------------------------------------------------------------------------
create or replace function public.set_meal_order(
  p_menu_id     uuid,
  p_ordered     boolean,
  p_guest_count integer default 0,
  p_user_id     uuid default null
)
returns jsonb
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid        uuid := private.require_user();
  v_menu       public.menus%rowtype;
  s            public.mess_settings%rowtype;
  v_target     uuid := coalesce(p_user_id, v_uid);
  v_is_manager boolean;
  v_order      public.meal_orders%rowtype;
  v_guests     integer := case when p_ordered then coalesce(p_guest_count, 0) else 0 end;
  v_units      integer;
  v_new_cost   numeric(10,2) := 0;
  v_delta      numeric(10,2);
  v_balance    numeric;
begin
  select * into v_menu from public.menus where id = p_menu_id;
  if not found then
    raise exception 'menu_not_found';
  end if;
  select * into s from public.mess_settings where mess_id = v_menu.mess_id;

  v_is_manager := coalesce(private.managed_mess_id() = v_menu.mess_id, false);
  if v_target <> v_uid and not v_is_manager then
    raise exception 'not_manager';
  end if;
  if not private.is_active_member(v_menu.mess_id, v_target) then
    raise exception 'not_member';
  end if;
  if private.is_month_closed(v_menu.mess_id, v_menu.menu_date) then
    raise exception 'month_closed';
  end if;
  if not v_is_manager then
    if v_menu.is_locked then
      raise exception 'menu_locked';
    end if;
    if now() > v_menu.cutoff_at then
      raise exception 'cutoff_passed';
    end if;
  end if;
  if v_guests < 0 or v_guests > s.max_guests_per_meal then
    raise exception 'too_many_guests';
  end if;
  if v_guests > 0 and not s.guest_meal_allowed then
    raise exception 'guests_not_allowed';
  end if;

  v_units := case when p_ordered then 1 + v_guests else 0 end;

  select * into v_order from public.meal_orders where menu_id = p_menu_id and user_id = v_target for update;

  if s.meal_rate_mode = 'fixed' then
    v_new_cost := v_menu.price * v_units;
    v_delta := v_new_cost - coalesce(v_order.charged_amount, 0);
    if v_delta > 0 then
      v_balance := private.balance_of(v_menu.mess_id, v_target);
      if v_balance - v_delta < -s.credit_limit then
        raise exception 'insufficient_balance'
          using hint = 'Balance ' || v_balance || ', needed ' || v_delta;
      end if;
    end if;
  end if;

  if v_order.id is null then
    if not p_ordered then
      return jsonb_build_object('order_id', null, 'status', 'cancelled', 'guest_count', 0, 'charged_amount', 0);
    end if;
    insert into public.meal_orders (mess_id, menu_id, user_id, status, guest_count, charged_amount, ordered_by)
    values (v_menu.mess_id, p_menu_id, v_target, 'ordered', v_guests, v_new_cost, v_uid)
    returning * into v_order;
  else
    update public.meal_orders
       set status = case when p_ordered then 'ordered'::public.order_status else 'cancelled'::public.order_status end,
           guest_count = v_guests,
           charged_amount = v_new_cost,
           ordered_by = v_uid
     where id = v_order.id
     returning * into v_order;
  end if;

  if s.meal_rate_mode = 'fixed' and v_delta <> 0 then
    insert into public.ledger_entries (mess_id, user_id, entry_type, amount, description, period_month, ref_table, ref_id, created_by)
    values (v_menu.mess_id, v_target,
            case when v_delta > 0 then 'meal_charge'::public.ledger_type else 'meal_refund'::public.ledger_type end,
            -v_delta,
            case v_menu.slot when 'breakfast' then 'সকালের মিল' when 'lunch' then 'দুপুরের মিল' else 'রাতের মিল' end
              || ' · ' || to_char(v_menu.menu_date, 'DD Mon') || case when v_guests > 0 then ' (+' || v_guests || ' অতিথি)' else '' end,
            private.month_start(v_menu.menu_date), 'meal_orders', v_order.id, v_uid);
  end if;

  return jsonb_build_object(
    'order_id', v_order.id,
    'status', v_order.status,
    'guest_count', v_order.guest_count,
    'charged_amount', v_order.charged_amount,
    'balance', private.balance_of(v_menu.mess_id, v_target));
end;
$$;

-- Meal units per member for a month (guests count as extra meals; slot weights
-- come from the mess settings).
create or replace function private.meal_units(p_mess uuid, p_month date)
returns table (user_id uuid, units numeric)
language sql stable security definer
set search_path = ''
as $$
  select o.user_id,
         sum((1 + o.guest_count) * case m.slot when 'breakfast' then s.breakfast_weight
                                               when 'lunch' then s.lunch_weight
                                               else s.dinner_weight end)::numeric as units
  from public.meal_orders o
  join public.menus m on m.id = o.menu_id
  join public.mess_settings s on s.mess_id = m.mess_id
  where m.mess_id = p_mess
    and o.status = 'ordered'
    and m.menu_date >= private.month_start(p_month)
    and m.menu_date < (private.month_start(p_month) + interval '1 month')::date
  group by o.user_id
$$;

-- Headcount per slot for a day (for the bua / kitchen list).
create or replace function public.get_meal_headcount(p_date date default null)
returns table (menu_id uuid, slot public.meal_slot, items text, members bigint, guests bigint, total bigint)
language plpgsql stable security definer
set search_path = ''
as $$
declare
  v_mess uuid := private.current_mess_id();
begin
  perform private.require_user();
  if v_mess is null then
    raise exception 'not_in_mess';
  end if;
  return query
    select m.id, m.slot, m.items,
           count(o.id) filter (where o.status = 'ordered'),
           coalesce(sum(o.guest_count) filter (where o.status = 'ordered'), 0)::bigint,
           (count(o.id) filter (where o.status = 'ordered')
             + coalesce(sum(o.guest_count) filter (where o.status = 'ordered'), 0))::bigint
    from public.menus m
    left join public.meal_orders o on o.menu_id = m.id
    where m.mess_id = v_mess and m.menu_date = coalesce(p_date, private.dhaka_today())
    group by m.id, m.slot, m.items
    order by m.slot;
end;
$$;


-- >>> 0005_billing.sql
-- =============================================================================
-- MessMate BD · 0005 · Expenses, bills, bill splitting, monthly closing
--
-- Expenses   bazar / cooking gas feed the meal rate; other categories are
--            "shared expenses" split equally at close (if enabled).
-- Bills      rent / utilities / bua salary, split equally, by room rent or
--            custom, posted as bill_share ledger entries.
-- Closing    computes the meal rate, posts meal + shared charges, writes one
--            statement per member and locks the month.
-- =============================================================================

create table public.expenses (
  id                      uuid primary key default gen_random_uuid(),
  mess_id                 uuid not null references public.messes (id) on delete cascade,
  category                public.expense_category not null default 'bazar',
  amount                  numeric(12,2) not null check (amount > 0 and amount <= 1000000),
  expense_date            date not null default private.dhaka_today(),
  description             text check (char_length(description) <= 300),
  receipt_path            text check (char_length(receipt_path) <= 300),
  paid_from               public.expense_payer not null default 'mess_fund',
  paid_by                 uuid references public.profiles (id) on delete restrict,
  reimbursement_entry_id  uuid references public.ledger_entries (id) on delete restrict,
  added_by                uuid references public.profiles (id) on delete set null,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  constraint expense_member_payer check (paid_from = 'mess_fund' or paid_by is not null)
);
create index expenses_mess_date_idx on public.expenses (mess_id, expense_date);

-- If a member paid from their own pocket, credit them right away
-- (reimbursement). Closed months are frozen.
create or replace function private.expense_guard()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  v_entry uuid;
begin
  if private.is_purge() then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_op = 'DELETE' then
    if private.is_month_closed(old.mess_id, old.expense_date) then
      raise exception 'month_closed';
    end if;
    if old.reimbursement_entry_id is not null
       and not exists (select 1 from public.ledger_entries where reverses_id = old.reimbursement_entry_id) then
      insert into public.ledger_entries (mess_id, user_id, entry_type, amount, description, period_month, reverses_id, created_by)
      values (old.mess_id, old.paid_by, 'reversal', -old.amount, 'খরচ মুছে ফেলা হয়েছে · ফেরত বাতিল',
              private.month_start(old.expense_date), old.reimbursement_entry_id, auth.uid());
    end if;
    return old;
  end if;

  if private.is_month_closed(new.mess_id, new.expense_date) then
    raise exception 'month_closed';
  end if;
  if new.expense_date > private.dhaka_today() + 1 then
    raise exception 'future_date';
  end if;

  if tg_op = 'UPDATE' then
    if new.mess_id <> old.mess_id then
      raise exception 'expense_identity_locked';
    end if;
    if private.is_month_closed(old.mess_id, old.expense_date) then
      raise exception 'month_closed';
    end if;
    if new.paid_from is distinct from old.paid_from or new.paid_by is distinct from old.paid_by then
      raise exception 'expense_payer_locked';
    end if;
    if old.reimbursement_entry_id is not null
       and (new.amount <> old.amount or private.month_start(new.expense_date) <> private.month_start(old.expense_date)) then
      raise exception 'expense_reimbursed_locked';
    end if;
    new.reimbursement_entry_id := old.reimbursement_entry_id;
    new.added_by := old.added_by;
    return new;
  end if;

  -- INSERT
  new.added_by := coalesce(auth.uid(), new.added_by);
  new.reimbursement_entry_id := null;
  if new.paid_from = 'member' then
    if not exists (select 1 from public.mess_members
                   where mess_id = new.mess_id and user_id = new.paid_by and status in ('active', 'inactive')) then
      raise exception 'payer_not_member';
    end if;
    insert into public.ledger_entries (mess_id, user_id, entry_type, amount, description, period_month, ref_table, ref_id, created_by)
    values (new.mess_id, new.paid_by, 'reimbursement', new.amount,
            'নিজের টাকায় খরচ ফেরত · ' || coalesce(left(new.description, 60), new.category::text),
            private.month_start(new.expense_date), 'expenses', new.id, new.added_by)
    returning id into v_entry;
    new.reimbursement_entry_id := v_entry;
  end if;
  return new;
end;
$$;

create trigger expenses_guard before insert or update or delete on public.expenses
  for each row execute function private.expense_guard();
create trigger expenses_updated_at before update on public.expenses
  for each row execute function private.set_updated_at();
create trigger expenses_audit after insert or update or delete on public.expenses
  for each row execute function private.audit_row();

-- -----------------------------------------------------------------------------
-- Bills
-- -----------------------------------------------------------------------------
create table public.bills (
  id            uuid primary key default gen_random_uuid(),
  mess_id       uuid not null references public.messes (id) on delete cascade,
  bill_type     public.bill_type not null,
  period_month  date not null check (period_month = date_trunc('month', period_month::timestamp)::date),
  total_amount  numeric(12,2) not null check (total_amount >= 0 and total_amount <= 10000000),
  split_mode    public.split_mode not null default 'equal',
  due_date      date,
  description   text check (char_length(description) <= 300),
  status        public.bill_status not null default 'draft',
  posted_at     timestamptz,
  posted_by     uuid references public.profiles (id) on delete set null,
  voided_at     timestamptz,
  void_reason   text check (char_length(void_reason) <= 200),
  created_by    uuid references public.profiles (id) on delete set null,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now()
);
create index bills_mess_period_idx on public.bills (mess_id, period_month);

create table public.bill_shares (
  id               uuid primary key default gen_random_uuid(),
  bill_id          uuid not null references public.bills (id) on delete restrict,
  mess_id          uuid not null references public.messes (id) on delete cascade,
  user_id          uuid not null references public.profiles (id) on delete restrict,
  amount           numeric(12,2) not null check (amount >= 0),
  ledger_entry_id  uuid references public.ledger_entries (id) on delete restrict,
  created_at       timestamptz not null default now(),
  unique (bill_id, user_id)
);
create index bill_shares_user_idx on public.bill_shares (user_id);
create index bill_shares_mess_idx on public.bill_shares (mess_id);

-- Drafts are editable by managers; posting / voiding happens only via RPC.
create or replace function private.bill_guard()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  if private.is_purge() or private.is_internal() then
    return case when tg_op = 'DELETE' then old else new end;
  end if;

  if tg_op = 'DELETE' then
    if old.status <> 'draft' then
      raise exception 'bill_not_draft';
    end if;
    return old;
  end if;

  if tg_op = 'INSERT' then
    new.status := 'draft';
    new.posted_at := null;
    new.posted_by := null;
    new.voided_at := null;
    new.void_reason := null;
    new.created_by := coalesce(auth.uid(), new.created_by);
  else
    if old.status <> 'draft' then
      raise exception 'bill_not_draft';
    end if;
    if new.status <> 'draft' then
      raise exception 'use_post_bill';
    end if;
    if new.mess_id <> old.mess_id then
      raise exception 'bill_identity_locked';
    end if;
  end if;

  if private.is_month_closed(new.mess_id, new.period_month) then
    raise exception 'month_closed';
  end if;
  return new;
end;
$$;

create trigger bills_guard before insert or update or delete on public.bills
  for each row execute function private.bill_guard();
create trigger bills_updated_at before update on public.bills
  for each row execute function private.set_updated_at();
create trigger bills_audit after insert or update or delete on public.bills
  for each row execute function private.audit_row();

create table public.member_statements (
  id               uuid primary key default gen_random_uuid(),
  closing_id       uuid not null references public.monthly_closings (id) on delete restrict,
  mess_id          uuid not null references public.messes (id) on delete cascade,
  user_id          uuid not null references public.profiles (id) on delete restrict,
  period_month     date not null,
  opening_balance  numeric(12,2) not null,
  deposits         numeric(12,2) not null,
  meal_units       numeric(10,2) not null,
  meal_cost        numeric(12,2) not null,
  bill_cost        numeric(12,2) not null,
  other_net        numeric(12,2) not null,
  closing_balance  numeric(12,2) not null,
  created_at       timestamptz not null default now(),
  unique (closing_id, user_id)
);
create index member_statements_user_idx on public.member_statements (user_id, period_month desc);
create index member_statements_mess_idx on public.member_statements (mess_id, period_month desc);

create trigger monthly_closings_audit after insert on public.monthly_closings
  for each row execute function private.audit_row();

-- Members who belonged to the mess at any point during the month.
create or replace function private.month_participants(p_mess uuid, p_month date)
returns table (user_id uuid, room_id uuid)
language sql stable security definer
set search_path = ''
as $$
  select distinct on (mm.user_id) mm.user_id, mm.room_id
  from public.mess_members mm
  where mm.mess_id = p_mess
    and mm.status in ('active', 'inactive', 'left')
    and mm.joined_at is not null
    and mm.joined_at < private.dhaka_ts((private.month_start(p_month) + interval '1 month')::date, '00:00')
    and (mm.left_at is null or mm.left_at >= private.dhaka_ts(private.month_start(p_month), '00:00'))
  order by mm.user_id, mm.joined_at desc
$$;

create or replace function private.bill_label(p_type public.bill_type)
returns text
language sql immutable
set search_path = ''
as $$
  select case p_type
    when 'rent' then 'ভাড়া'
    when 'electricity' then 'বিদ্যুৎ বিল'
    when 'gas' then 'গ্যাস বিল'
    when 'water' then 'পানির বিল'
    when 'wifi' then 'ওয়াইফাই বিল'
    when 'bua' then 'বুয়ার বেতন'
    when 'service_charge' then 'সার্ভিস চার্জ'
    else 'অন্যান্য বিল'
  end
$$;

-- Post a draft bill: split it and charge every share to the ledger.
--   equal   : total split across the month's members (paisa remainder spread)
--   by_room : each room's monthly_rent split among its occupants; total becomes the sum
--   custom  : p_custom = [{"user_id": "...", "amount": 1200}, ...] must sum to total
create or replace function public.post_bill(p_bill_id uuid, p_custom jsonb default null)
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid     uuid := auth.uid();
  v_bill    public.bills%rowtype;
  v_users   uuid[];
  v_amounts numeric[];
  v_n       integer;
  v_cents   bigint;
  v_base    bigint;
  v_rem     integer;
  v_share   uuid;
  v_entry   uuid;
  v_total   numeric(12,2);
  v_label   text;
begin
  select * into v_bill from public.bills where id = p_bill_id for update;
  if not found then
    raise exception 'not_found';
  end if;
  if not private.is_system_call() and private.managed_mess_id() is distinct from v_bill.mess_id then
    raise exception 'not_manager';
  end if;
  if v_bill.status <> 'draft' then
    raise exception 'bill_not_draft';
  end if;
  if private.is_month_closed(v_bill.mess_id, v_bill.period_month) then
    raise exception 'month_closed';
  end if;

  if v_bill.split_mode = 'equal' then
    select array_agg(p.user_id order by p.user_id) into v_users
      from private.month_participants(v_bill.mess_id, v_bill.period_month) p;
    v_n := coalesce(cardinality(v_users), 0);
    if v_n = 0 then
      raise exception 'no_participants';
    end if;
    v_cents := round(v_bill.total_amount * 100);
    v_base := v_cents / v_n;
    v_rem := (v_cents - v_base * v_n)::integer;
    v_amounts := array[]::numeric[];
    for i in 1..v_n loop
      v_amounts := v_amounts || ((v_base + case when i <= v_rem then 1 else 0 end) / 100.0)::numeric;
    end loop;

  elsif v_bill.split_mode = 'by_room' then
    select array_agg(x.user_id order by x.user_id), array_agg(x.amount order by x.user_id)
      into v_users, v_amounts
      from (select p.user_id,
                   round(r.monthly_rent / count(*) over (partition by p.room_id), 2) as amount
              from private.month_participants(v_bill.mess_id, v_bill.period_month) p
              join public.mess_rooms r on r.id = p.room_id) x;
    v_n := coalesce(cardinality(v_users), 0);
    if v_n = 0 then
      raise exception 'no_participants';
    end if;

  else
    if p_custom is null or jsonb_typeof(p_custom) <> 'array' or jsonb_array_length(p_custom) = 0 then
      raise exception 'custom_split_required';
    end if;
    select array_agg(c.user_id order by c.user_id), array_agg(round(c.amount, 2) order by c.user_id)
      into v_users, v_amounts
      from jsonb_to_recordset(p_custom) as c(user_id uuid, amount numeric);
    v_n := cardinality(v_users);
    if (select count(distinct u) from unnest(v_users) u) <> v_n then
      raise exception 'custom_split_duplicate_user';
    end if;
    if exists (select 1 from unnest(v_amounts) a where a is null or a < 0) then
      raise exception 'invalid_amount';
    end if;
    if exists (select 1 from unnest(v_users) u
               where u is null or u not in (select p.user_id from private.month_participants(v_bill.mess_id, v_bill.period_month) p)) then
      raise exception 'custom_split_not_member';
    end if;
    if abs((select sum(a) from unnest(v_amounts) a) - v_bill.total_amount) >= 0.01 then
      raise exception 'custom_split_mismatch';
    end if;
  end if;

  v_label := private.bill_label(v_bill.bill_type) || ' · ' || to_char(v_bill.period_month, 'Mon YYYY');
  v_total := 0;
  for i in 1..v_n loop
    v_share := gen_random_uuid();
    v_entry := null;
    if v_amounts[i] > 0 then
      insert into public.ledger_entries (mess_id, user_id, entry_type, amount, description, period_month, ref_table, ref_id, created_by)
      values (v_bill.mess_id, v_users[i], 'bill_share', -v_amounts[i], v_label, v_bill.period_month, 'bill_shares', v_share, v_uid)
      returning id into v_entry;
    end if;
    insert into public.bill_shares (id, bill_id, mess_id, user_id, amount, ledger_entry_id)
    values (v_share, v_bill.id, v_bill.mess_id, v_users[i], v_amounts[i], v_entry);
    v_total := v_total + v_amounts[i];

    perform private.notify(v_users[i], v_bill.mess_id, 'bill_posted', 'নতুন বিল: ' || private.bill_label(v_bill.bill_type),
      'আপনার ভাগ ' || private.taka(v_amounts[i]) || ' (' || to_char(v_bill.period_month, 'Mon YYYY') || ')।',
      '/billing', jsonb_build_object('bill_id', v_bill.id, 'amount', v_amounts[i]));
  end loop;

  perform private.set_internal(true);
  update public.bills
     set status = 'posted', posted_at = now(), posted_by = v_uid,
         total_amount = case when v_bill.split_mode = 'by_room' then v_total else total_amount end
   where id = v_bill.id;
  perform private.set_internal(false);
  return v_n;
end;
$$;

create or replace function public.void_bill(p_bill_id uuid, p_reason text)
returns void
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid    uuid := private.require_user();
  v_bill   public.bills%rowtype;
  v_reason text := left(nullif(trim(p_reason), ''), 200);
  r        record;
begin
  select * into v_bill from public.bills where id = p_bill_id for update;
  if not found then
    raise exception 'not_found';
  end if;
  if private.managed_mess_id() is distinct from v_bill.mess_id then
    raise exception 'not_manager';
  end if;
  if v_bill.status <> 'posted' then
    raise exception 'bill_not_posted';
  end if;
  if private.is_month_closed(v_bill.mess_id, v_bill.period_month) then
    raise exception 'month_closed';
  end if;
  if v_reason is null or char_length(v_reason) < 3 then
    raise exception 'reason_required';
  end if;

  for r in select bs.user_id, l.id as entry_id, l.amount
             from public.bill_shares bs
             join public.ledger_entries l on l.id = bs.ledger_entry_id
            where bs.bill_id = v_bill.id loop
    insert into public.ledger_entries (mess_id, user_id, entry_type, amount, description, period_month, reverses_id, created_by)
    values (v_bill.mess_id, r.user_id, 'reversal', -r.amount, 'বিল বাতিল: ' || v_reason, v_bill.period_month, r.entry_id, v_uid);
    perform private.notify(r.user_id, v_bill.mess_id, 'bill_voided', 'বিল বাতিল হয়েছে: ' || private.bill_label(v_bill.bill_type),
      private.taka(-r.amount) || ' ফেরত দেওয়া হয়েছে। কারণ: ' || v_reason, '/billing');
  end loop;

  perform private.set_internal(true);
  update public.bills set status = 'void', voided_at = now(), void_reason = v_reason where id = v_bill.id;
  perform private.set_internal(false);
end;
$$;

-- -----------------------------------------------------------------------------
-- Monthly closing
-- -----------------------------------------------------------------------------
create or replace function public.close_month(p_mess_id uuid, p_month date)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid            uuid := auth.uid();
  v_month          date := private.month_start(p_month);
  v_next           date := (private.month_start(p_month) + interval '1 month')::date;
  s                public.mess_settings%rowtype;
  v_closing        uuid := gen_random_uuid();
  v_meal_expense   numeric(12,2);
  v_shared_expense numeric(12,2);
  v_total_units    numeric(12,2);
  v_rate           numeric(12,4) := 0;
  v_users          uuid[];
  v_n              integer;
  v_cents          bigint;
  v_base           bigint;
  v_rem            integer;
  v_amount         numeric(12,2);
  v_bills          numeric(12,2);
  v_deposits       numeric(12,2);
  v_members        integer;
  r                record;
begin
  if not private.is_system_call() and private.managed_mess_id() is distinct from p_mess_id then
    raise exception 'not_manager';
  end if;
  if v_month >= private.month_start(private.dhaka_today()) then
    raise exception 'month_not_finished';
  end if;
  perform pg_advisory_xact_lock(hashtext('close_month:' || p_mess_id::text || ':' || v_month::text));
  if private.is_month_closed(p_mess_id, v_month) then
    raise exception 'month_already_closed';
  end if;
  select * into s from public.mess_settings where mess_id = p_mess_id;
  if not found then
    raise exception 'mess_settings_missing';
  end if;

  select coalesce(sum(e.amount) filter (where e.category in ('bazar', 'cooking_gas')), 0),
         coalesce(sum(e.amount) filter (where e.category not in ('bazar', 'cooking_gas')), 0)
    into v_meal_expense, v_shared_expense
    from public.expenses e
   where e.mess_id = p_mess_id and e.expense_date >= v_month and e.expense_date < v_next;

  select coalesce(sum(u.units), 0) into v_total_units from private.meal_units(p_mess_id, v_month) u;
  if v_total_units > 0 then
    v_rate := round(v_meal_expense / v_total_units, 4);
  end if;

  -- 1) auto mode: everyone pays their meal units × the month's meal rate
  if s.meal_rate_mode = 'auto' and v_rate > 0 then
    for r in select u.user_id, u.units from private.meal_units(p_mess_id, v_month) u where u.units > 0 loop
      v_amount := round(r.units * v_rate, 2);
      if v_amount > 0 then
        insert into public.ledger_entries (mess_id, user_id, entry_type, amount, description, period_month, ref_table, ref_id, created_by)
        values (p_mess_id, r.user_id, 'meal_charge', -v_amount,
                'মাসিক মিল খরচ · ' || trim(to_char(r.units, 'FM99990.##')) || ' মিল × ' || private.taka(v_rate),
                v_month, 'monthly_closings', v_closing, v_uid);
      end if;
    end loop;
  end if;

  -- 2) shared (non-meal) expenses split equally among the month's members
  if s.split_shared_expenses and v_shared_expense > 0 then
    select array_agg(p.user_id order by p.user_id) into v_users
      from private.month_participants(p_mess_id, v_month) p;
    v_n := coalesce(cardinality(v_users), 0);
    if v_n > 0 then
      v_cents := round(v_shared_expense * 100);
      v_base := v_cents / v_n;
      v_rem := (v_cents - v_base * v_n)::integer;
      for i in 1..v_n loop
        v_amount := (v_base + case when i <= v_rem then 1 else 0 end) / 100.0;
        if v_amount > 0 then
          insert into public.ledger_entries (mess_id, user_id, entry_type, amount, description, period_month, ref_table, ref_id, created_by)
          values (p_mess_id, v_users[i], 'bill_share', -v_amount, 'শেয়ার্ড খরচ (পরিষ্কার, মেরামত, অন্যান্য)',
                  v_month, 'monthly_closings', v_closing, v_uid);
        end if;
      end loop;
    end if;
  end if;

  select coalesce(sum(b.total_amount), 0) into v_bills
    from public.bills b where b.mess_id = p_mess_id and b.period_month = v_month and b.status = 'posted';
  select coalesce(sum(l.amount), 0) into v_deposits
    from public.ledger_entries l where l.mess_id = p_mess_id and l.period_month = v_month and l.entry_type = 'deposit';

  -- 3) lock the month (from here on the ledger rejects entries for it)
  insert into public.monthly_closings (id, mess_id, period_month, meal_rate_mode, total_meal_units, total_meal_expense,
                                       meal_rate, total_shared_expense, total_bills, total_deposits, closed_by)
  values (v_closing, p_mess_id, v_month, s.meal_rate_mode, v_total_units, v_meal_expense,
          v_rate, v_shared_expense, v_bills, v_deposits, v_uid);

  -- 4) one statement per member (participants + anyone with ledger activity)
  insert into public.member_statements (closing_id, mess_id, user_id, period_month, opening_balance, deposits,
                                        meal_units, meal_cost, bill_cost, other_net, closing_balance)
  select v_closing, p_mess_id, x.user_id, v_month,
         coalesce((select sum(lo.amount) from public.ledger_entries lo
                    where lo.mess_id = p_mess_id and lo.user_id = x.user_id and lo.period_month < v_month), 0),
         coalesce(sum(l.amount) filter (where l.entry_type = 'deposit'), 0),
         coalesce((select u.units from private.meal_units(p_mess_id, v_month) u where u.user_id = x.user_id), 0),
         -coalesce(sum(l.amount) filter (where l.entry_type in ('meal_charge', 'meal_refund')), 0),
         -coalesce(sum(l.amount) filter (where l.entry_type = 'bill_share'), 0),
         coalesce(sum(l.amount) filter (where l.entry_type in ('reimbursement', 'adjustment', 'refund_payout', 'reversal')), 0),
         0
    from (select p.user_id from private.month_participants(p_mess_id, v_month) p
          union
          select l2.user_id from public.ledger_entries l2
           where l2.mess_id = p_mess_id and l2.period_month = v_month) x
    left join public.ledger_entries l
      on l.mess_id = p_mess_id and l.user_id = x.user_id and l.period_month = v_month
   group by x.user_id;

  update public.member_statements
     set closing_balance = opening_balance + deposits - meal_cost - bill_cost + other_net
   where closing_id = v_closing;

  select count(*) into v_members from public.member_statements where closing_id = v_closing;
  update public.monthly_closings set member_count = v_members where id = v_closing;

  for r in select ms.user_id, ms.closing_balance from public.member_statements ms where ms.closing_id = v_closing loop
    perform private.notify(r.user_id, p_mess_id, 'month_closed',
      to_char(v_month, 'Mon YYYY') || ' মাসের হিসাব বন্ধ হয়েছে',
      'মিল রেট ' || private.taka(v_rate) || '। মাস শেষে আপনার ব্যালেন্স ' || private.taka(r.closing_balance) || '।',
      '/billing', jsonb_build_object('closing_id', v_closing, 'period_month', v_month));
  end loop;

  return v_closing;
end;
$$;

-- pg_cron: close last month for every mess with auto-close on, once the grace
-- days have passed. Failures are reported as warnings and retried next day.
create or replace function private.auto_close_due_months()
returns integer
language plpgsql security definer
set search_path = ''
as $$
declare
  v_today date := private.dhaka_today();
  v_prev  date := (private.month_start(private.dhaka_today()) - interval '1 month')::date;
  v_count integer := 0;
  r       record;
begin
  for r in select m.id
             from public.messes m
             join public.mess_settings s on s.mess_id = m.id
            where m.is_active and s.auto_close_enabled
              and extract(day from v_today) >= s.auto_close_day
              and not private.is_month_closed(m.id, v_prev)
              and (exists (select 1 from public.menus mn where mn.mess_id = m.id
                            and mn.menu_date >= v_prev and mn.menu_date < private.month_start(v_today))
                   or exists (select 1 from public.ledger_entries l where l.mess_id = m.id and l.period_month = v_prev)
                   or exists (select 1 from public.expenses e where e.mess_id = m.id
                               and e.expense_date >= v_prev and e.expense_date < private.month_start(v_today))) loop
    begin
      perform public.close_month(r.id, v_prev);
      v_count := v_count + 1;
    exception when others then
      raise warning 'auto close failed for mess %: %', r.id, sqlerrm;
    end;
  end loop;
  return v_count;
end;
$$;


-- >>> 0006_housing.sql
-- =============================================================================
-- MessMate BD · 0006 · Housing: listings, roommate matching, rent tracker,
-- move-in / move-out checklists
-- =============================================================================

create table public.listings (
  id                uuid primary key default gen_random_uuid(),
  owner_id          uuid not null references public.profiles (id) on delete cascade,
  listing_type      public.listing_type not null,
  title             text not null check (char_length(title) between 5 and 120),
  description       text check (char_length(description) <= 2000),
  area_id           smallint not null references public.areas (id),
  address_line      text check (char_length(address_line) <= 200),
  lat               numeric(9,6) check (lat between 20 and 27),
  lng               numeric(9,6) check (lng between 88 and 93),
  rent              numeric(10,2) not null check (rent >= 0 and rent <= 1000000),
  advance_deposit   numeric(10,2) not null default 0 check (advance_deposit >= 0),
  available_from    date,
  gender_pref       public.gender_pref not null default 'any',
  tenant_pref       public.tenant_pref not null default 'any',
  seats_available   smallint not null default 1 check (seats_available between 0 and 50),
  facilities        text[] not null default '{}' check (facilities <@ array[
                      'wifi', 'gas', 'lift', 'generator', 'ips', 'attached_bath', 'balcony', 'parking',
                      'security', 'cctv', 'water_filter', 'furnished', 'kitchen', 'meal_system', 'laundry']::text[]),
  contact_name      text check (char_length(contact_name) <= 80),
  contact_phone     text not null check (contact_phone ~ '^\+?[0-9]{10,14}$'),
  status            public.moderation_status not null default 'pending',
  is_filled         boolean not null default false,
  rejection_reason  text check (char_length(rejection_reason) <= 300),
  moderated_by      uuid references public.profiles (id) on delete set null,
  moderated_at      timestamptz,
  created_at        timestamptz not null default now(),
  updated_at        timestamptz not null default now()
);
create index listings_browse_idx on public.listings (status, area_id, listing_type, rent);
create index listings_owner_idx on public.listings (owner_id);

create table public.listing_photos (
  id            uuid primary key default gen_random_uuid(),
  listing_id    uuid not null references public.listings (id) on delete cascade,
  storage_path  text not null check (char_length(storage_path) <= 300),
  sort_order    smallint not null default 0,
  created_at    timestamptz not null default now()
);
create index listing_photos_listing_idx on public.listing_photos (listing_id, sort_order);

create table public.saved_listings (
  user_id     uuid not null references public.profiles (id) on delete cascade,
  listing_id  uuid not null references public.listings (id) on delete cascade,
  created_at  timestamptz not null default now(),
  primary key (user_id, listing_id)
);

-- Generic moderation guard for community content (listings, services, recipes,
-- events, jobs, market). Owners can edit/archive; content edits go back to
-- review; only super admins approve or reject.
create or replace function private.guard_listing()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  v_active integer;
begin
  if private.is_system_call() or private.is_internal() or private.is_super_admin() then
    return new;
  end if;

  if tg_op = 'INSERT' then
    perform private.check_rate_limit('listing:' || auth.uid(), 5, interval '1 day');
    select count(*) into v_active from public.listings
     where owner_id = auth.uid() and status in ('pending', 'approved');
    if v_active >= 10 then
      raise exception 'too_many_listings';
    end if;
    new.owner_id := auth.uid();
    new.status := 'pending';
    new.rejection_reason := null;
    new.moderated_by := null;
    new.moderated_at := null;
    return new;
  end if;

  new.owner_id := old.owner_id;
  new.moderated_by := old.moderated_by;
  new.moderated_at := old.moderated_at;
  new.created_at := old.created_at;
  if new.status is distinct from old.status and new.status <> 'archived'
     and not (old.status = 'archived' and new.status = 'pending') then
    new.status := old.status;
  end if;
  if (new.listing_type, new.title, new.description, new.area_id, new.address_line, new.rent,
      new.advance_deposit, new.contact_phone, new.facilities)
     is distinct from
     (old.listing_type, old.title, old.description, old.area_id, old.address_line, old.rent,
      old.advance_deposit, old.contact_phone, old.facilities)
     and new.status <> 'archived' then
    new.status := 'pending';
  end if;
  return new;
end;
$$;

create trigger listings_guard before insert or update on public.listings
  for each row execute function private.guard_listing();
create trigger listings_updated_at before update on public.listings
  for each row execute function private.set_updated_at();
create trigger listings_audit after update of status on public.listings
  for each row execute function private.audit_row();

create or replace function private.guard_listing_photo()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
declare
  v_owner uuid;
begin
  select owner_id into v_owner from public.listings where id = new.listing_id;
  if not private.is_system_call() and new.storage_path not like v_owner::text || '/%' then
    raise exception 'invalid_photo_path';
  end if;
  if (select count(*) from public.listing_photos where listing_id = new.listing_id) >= 8 then
    raise exception 'too_many_photos';
  end if;
  return new;
end;
$$;

create trigger listing_photos_guard before insert on public.listing_photos
  for each row execute function private.guard_listing_photo();

-- -----------------------------------------------------------------------------
-- Roommate matching
-- -----------------------------------------------------------------------------
create table public.roommate_profiles (
  user_id         uuid primary key references public.profiles (id) on delete cascade,
  is_active       boolean not null default true,
  gender          public.gender_type not null,
  occupation      public.occupation_type not null,
  budget_min      numeric(10,2) not null check (budget_min >= 0),
  budget_max      numeric(10,2) not null check (budget_max <= 200000),
  smoking         boolean not null default false,
  sleep_schedule  text not null default 'flexible' check (sleep_schedule in ('early', 'late', 'flexible')),
  cleanliness     smallint not null default 3 check (cleanliness between 1 and 5),
  food_pref       text not null default 'any' check (food_pref in ('any', 'halal_only', 'vegetarian')),
  guests_ok       boolean not null default true,
  move_in_date    date,
  about           text check (char_length(about) <= 500),
  contact_phone   text check (contact_phone ~ '^\+?[0-9]{10,14}$'),
  show_phone      boolean not null default false,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  constraint roommate_budget_range check (budget_max >= budget_min)
);
create index roommate_profiles_active_idx on public.roommate_profiles (gender, is_active);

create table public.roommate_area_prefs (
  user_id  uuid not null references public.roommate_profiles (user_id) on delete cascade,
  area_id  smallint not null references public.areas (id) on delete cascade,
  primary key (user_id, area_id)
);
create index roommate_area_prefs_area_idx on public.roommate_area_prefs (area_id);

create trigger roommate_profiles_updated_at before update on public.roommate_profiles
  for each row execute function private.set_updated_at();

-- Rule-based compatibility (0–100). Same-gender only; contact phone is shared
-- only when the other person opted in. Weights:
--   budget 25 · area 20 · smoking 15 · sleep 10 · cleanliness 10 ·
--   occupation 10 · food 5 · guests 5
create or replace function public.roommate_matches(p_limit integer default 20)
returns table (
  user_id        uuid,
  full_name      text,
  avatar_url     text,
  occupation     public.occupation_type,
  institution    text,
  budget_min     numeric,
  budget_max     numeric,
  smoking        boolean,
  sleep_schedule text,
  cleanliness    smallint,
  food_pref      text,
  guests_ok      boolean,
  move_in_date   date,
  about          text,
  area_names     text[],
  contact_phone  text,
  score          integer,
  reasons        text[]
)
language plpgsql stable security definer
set search_path = ''
as $$
declare
  v_uid uuid := private.require_user();
  me    public.roommate_profiles%rowtype;
  v_my_areas smallint[];
begin
  select * into me from public.roommate_profiles rp where rp.user_id = v_uid and rp.is_active;
  if not found then
    raise exception 'roommate_profile_required';
  end if;
  select coalesce(array_agg(ap.area_id), '{}') into v_my_areas
    from public.roommate_area_prefs ap where ap.user_id = v_uid;

  return query
  with cand as (
    select rp.*, p.full_name as c_name, p.avatar_url as c_avatar, p.institution as c_institution,
           coalesce((select array_agg(ap.area_id) from public.roommate_area_prefs ap where ap.user_id = rp.user_id), '{}') as c_areas
      from public.roommate_profiles rp
      join public.profiles p on p.id = rp.user_id
     where rp.is_active and rp.user_id <> v_uid and rp.gender = me.gender and not p.is_deleted
  ),
  scored as (
    select c.*,
           -- budget: full marks when ranges overlap, fading with the gap
           case when least(c.budget_max, me.budget_max) >= greatest(c.budget_min, me.budget_min) then 25
                else greatest(0, 25 - round(25 * (greatest(c.budget_min, me.budget_min) - least(c.budget_max, me.budget_max))
                                             / greatest(me.budget_max, 1)))::integer end as s_budget,
           case when c.c_areas && v_my_areas then 20
                when cardinality(c.c_areas) = 0 or cardinality(v_my_areas) = 0 then 10
                else 0 end as s_area,
           case when c.smoking = me.smoking then 15 else 0 end as s_smoking,
           case when c.sleep_schedule = me.sleep_schedule then 10
                when 'flexible' in (c.sleep_schedule, me.sleep_schedule) then 6
                else 0 end as s_sleep,
           greatest(0, round(10 - abs(c.cleanliness - me.cleanliness) * 2.5))::integer as s_clean,
           case when c.occupation = me.occupation then 10 else 4 end as s_occupation,
           case when c.food_pref = me.food_pref or 'any' in (c.food_pref, me.food_pref) then 5 else 0 end as s_food,
           case when c.guests_ok = me.guests_ok then 5 else 2 end as s_guests
      from cand c
  )
  select sc.user_id, sc.c_name, sc.c_avatar, sc.occupation, sc.c_institution,
         sc.budget_min, sc.budget_max, sc.smoking, sc.sleep_schedule, sc.cleanliness,
         sc.food_pref, sc.guests_ok, sc.move_in_date, sc.about,
         (select array_agg(a.name_bn order by a.sort_order) from public.areas a where a.id = any (sc.c_areas)),
         case when sc.show_phone then sc.contact_phone end,
         (sc.s_budget + sc.s_area + sc.s_smoking + sc.s_sleep + sc.s_clean + sc.s_occupation + sc.s_food + sc.s_guests)::integer,
         array_remove(array[
           case when sc.s_budget = 25 then 'budget' end,
           case when sc.s_area = 20 then 'area' end,
           case when sc.s_smoking = 15 then 'smoking' end,
           case when sc.s_sleep = 10 then 'sleep' end,
           case when sc.s_clean >= 8 then 'cleanliness' end,
           case when sc.s_occupation = 10 then 'occupation' end,
           case when sc.s_food = 5 then 'food' end,
           case when sc.s_guests = 5 then 'guests' end], null)
    from scored sc
   order by 17 desc, sc.updated_at desc
   limit least(greatest(coalesce(p_limit, 20), 1), 50);
end;
$$;

-- -----------------------------------------------------------------------------
-- Personal rent + deposit tracker
-- -----------------------------------------------------------------------------
create table public.rent_records (
  id                  uuid primary key default gen_random_uuid(),
  user_id             uuid not null references public.profiles (id) on delete cascade,
  title               text not null check (char_length(title) between 2 and 80),
  landlord_name       text check (char_length(landlord_name) <= 80),
  landlord_phone      text check (landlord_phone ~ '^\+?[0-9]{10,14}$'),
  property_address    text check (char_length(property_address) <= 200),
  monthly_rent        numeric(10,2) not null check (monthly_rent >= 0),
  advance_paid        numeric(10,2) not null default 0 check (advance_paid >= 0),
  security_deposit    numeric(10,2) not null default 0 check (security_deposit >= 0),
  rent_due_day        smallint not null default 5 check (rent_due_day between 1 and 28),
  agreement_start     date,
  agreement_end       date,
  notice_period_days  smallint check (notice_period_days between 0 and 365),
  agreement_notes     text check (char_length(agreement_notes) <= 3000),
  is_active           boolean not null default true,
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now(),
  constraint rent_agreement_dates check (agreement_end is null or agreement_start is null or agreement_end >= agreement_start)
);
create index rent_records_user_idx on public.rent_records (user_id);

create table public.rent_payments (
  id              uuid primary key default gen_random_uuid(),
  rent_record_id  uuid not null references public.rent_records (id) on delete cascade,
  user_id         uuid not null references public.profiles (id) on delete cascade,
  period_month    date not null check (period_month = date_trunc('month', period_month::timestamp)::date),
  amount          numeric(10,2) not null check (amount > 0),
  paid_on         date not null default private.dhaka_today(),
  method          public.payment_method not null default 'cash',
  note            text check (char_length(note) <= 200),
  created_at      timestamptz not null default now(),
  unique (rent_record_id, period_month)
);
create index rent_payments_user_idx on public.rent_payments (user_id, period_month desc);

create or replace function private.guard_rent_payment()
returns trigger
language plpgsql security definer
set search_path = ''
as $$
begin
  select r.user_id into new.user_id from public.rent_records r where r.id = new.rent_record_id;
  return new;
end;
$$;

create trigger rent_payments_owner before insert or update on public.rent_payments
  for each row execute function private.guard_rent_payment();
create trigger rent_records_updated_at before update on public.rent_records
  for each row execute function private.set_updated_at();

-- -----------------------------------------------------------------------------
-- Move-in / move-out checklist + handover record
-- -----------------------------------------------------------------------------
create table public.move_checklists (
  id                 uuid primary key default gen_random_uuid(),
  user_id            uuid not null references public.profiles (id) on delete cascade,
  kind               public.move_kind not null,
  title              text not null check (char_length(title) between 2 and 100),
  property_address   text check (char_length(property_address) <= 200),
  scheduled_date     date,
  handover_to        text check (char_length(handover_to) <= 80),
  handover_phone     text check (handover_phone ~ '^\+?[0-9]{10,14}$'),
  electricity_meter  numeric(12,2),
  gas_meter          numeric(12,2),
  water_meter        numeric(12,2),
  keys_count         smallint check (keys_count between 0 and 50),
  deposit_amount     numeric(10,2) check (deposit_amount >= 0),
  deposit_returned   numeric(10,2) check (deposit_returned >= 0),
  handover_notes     text check (char_length(handover_notes) <= 2000),
  completed_at       timestamptz,
  created_at         timestamptz not null default now(),
  updated_at         timestamptz not null default now()
);
create index move_checklists_user_idx on public.move_checklists (user_id, created_at desc);

create table public.move_checklist_items (
  id            uuid primary key default gen_random_uuid(),
  checklist_id  uuid not null references public.move_checklists (id) on delete cascade,
  label         text not null check (char_length(label) between 1 and 150),
  is_done       boolean not null default false,
  note          text check (char_length(note) <= 300),
  photo_path    text check (char_length(photo_path) <= 300),
  sort_order    smallint not null default 0,
  created_at    timestamptz not null default now()
);
create index move_checklist_items_list_idx on public.move_checklist_items (checklist_id, sort_order);

create trigger move_checklists_updated_at before update on public.move_checklists
  for each row execute function private.set_updated_at();

-- Creates a checklist pre-filled with a practical Dhaka template.
create or replace function public.create_move_checklist(
  p_kind    public.move_kind,
  p_title   text,
  p_address text default null,
  p_date    date default null
)
returns uuid
language plpgsql security definer
set search_path = ''
as $$
declare
  v_uid   uuid := private.require_user();
  v_id    uuid;
  v_items text[];
begin
  if (select count(*) from public.move_checklists where user_id = v_uid) >= 20 then
    raise exception 'too_many_checklists';
  end if;

  insert into public.move_checklists (user_id, kind, title, property_address, scheduled_date)
  values (v_uid, p_kind, trim(p_title), nullif(trim(p_address), ''), p_date)
  returning id into v_id;

  v_items := case p_kind
    when 'move_in' then array[
      'চুক্তিপত্র পড়ে সই করুন, একটি কপি নিজের কাছে রাখুন',
      'অগ্রিম ও জামানতের লিখিত রসিদ নিন',
      'বিদ্যুৎ, গ্যাস ও পানির মিটার রিডিং ছবি সহ লিখে রাখুন',
      'দরজা-জানালার লক ও সব চাবি গুনে বুঝে নিন',
      'ফ্যান, লাইট, সুইচ ও প্লাগ ঠিক আছে কিনা দেখুন',
      'বাথরুমের কল, ফ্লাশ ও পানির লিক চেক করুন',
      'দেয়াল ও মেঝের আগের দাগ/ক্ষতির ছবি তুলে রাখুন',
      'ইন্টারনেট সংযোগের ব্যবস্থা করুন',
      'বাড়িওয়ালা ও কেয়ারটেকারের নম্বর সেভ করুন',
      'কাছের ফার্মেসি, হাসপাতাল ও থানা চিনে নিন',
      'থানায় ভাড়াটিয়া তথ্য ফরম জমা দিন']
    else array[
      'চুক্তি অনুযায়ী বাড়িওয়ালাকে লিখিত নোটিশ দিন',
      'শেষ মাসের ভাড়া ও সব বিল পরিশোধ করুন',
      'মেস/ফ্ল্যাটের সব হিসাব মিলিয়ে নিন',
      'বিদ্যুৎ, গ্যাস ও পানির মিটার রিডিং ছবি সহ লিখে রাখুন',
      'রুম পরিষ্কার করে ছবি তুলে রাখুন',
      'সব চাবি বুঝিয়ে দিন',
      'জামানতের টাকা ফেরত নিন',
      'ইন্টারনেট/গ্যাস সংযোগ বাতিল বা হস্তান্তর করুন',
      'নতুন ঠিকানা জানান (অফিস, ব্যাংক, কুরিয়ার)',
      'হস্তান্তর নোটে দুই পক্ষের সই নিন']
  end;

  insert into public.move_checklist_items (checklist_id, label, sort_order)
  select v_id, t.label, t.ord::smallint
    from unnest(v_items) with ordinality as t(label, ord);
  return v_id;
end;
$$;


